-- Name: fn_authorized_pickup_exists(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_authorized_pickup_exists(p_tenant_id uuid, p_pickup_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS(SELECT 1 FROM authorized_pickups WHERE tenant_id = p_tenant_id AND id = p_pickup_id);
$$;


--
-- Name: fn_cancel_invoice(uuid, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_cancel_invoice(p_invoice_id uuid, p_cancelled_by character varying, p_reason text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE invoices
    SET status = 'Cancelled',
        voided_at = NOW(),
        voided_by = p_cancelled_by,
        void_reason = p_reason,
        updated_at = NOW()
    WHERE id = p_invoice_id AND amount_paid = 0;
    RETURN FOUND;
END;
$$;


--
-- Name: fn_create_branch(uuid, uuid, uuid, character varying, character varying, boolean, character varying, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_create_branch(p_id uuid, p_tenant_id uuid, p_organization_id uuid, p_name character varying, p_location character varying, p_is_active boolean, p_operational_status character varying, p_active_closure_id uuid, p_created_at timestamp with time zone, p_updated_at timestamp with time zone) RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, name character varying, location character varying, is_active boolean, operational_status character varying, active_closure_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    INSERT INTO branches (
        id,
        tenant_id,
        organization_id,
        name,
        location,
        is_active,
        operational_status,
        active_closure_id,
        created_at,
        updated_at
    )
    VALUES (
        p_id,
        p_tenant_id,
        p_organization_id,
        p_name,
        p_location,
        p_is_active,
        COALESCE(NULLIF(p_operational_status, ''), 'Open'),
        p_active_closure_id,
        p_created_at,
        p_updated_at
    )
    RETURNING
        branches.id,
        branches.tenant_id,
        branches.organization_id,
        branches.name,
        branches.location,
        branches.is_active,
        branches.operational_status,
        branches.active_closure_id,
        branches.created_at,
        branches.updated_at;
END;
$$;


