CREATE TABLE public.branch_closures (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    branch_id uuid NOT NULL,
    status character varying(32) NOT NULL,
    reason character varying(64) NOT NULL,
    description text,
    parent_announcement text,
    effective_start_at timestamp with time zone NOT NULL,
    effective_end_at timestamp with time zone,
    created_by uuid NOT NULL,
    created_by_role character varying(64),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    reopened_by uuid,
    reopened_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    affected_classroom_count integer DEFAULT 0 NOT NULL,
    cancelled_session_count integer DEFAULT 0 NOT NULL
);


--
-- Name: fn_create_branch_closure(uuid, uuid, uuid, character varying, character varying, text, text, timestamp with time zone, timestamp with time zone, uuid, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_create_branch_closure(p_tenant_id uuid, p_organization_id uuid, p_branch_id uuid, p_status character varying, p_reason character varying, p_description text, p_parent_announcement text, p_effective_start_at timestamp with time zone, p_effective_end_at timestamp with time zone, p_created_by uuid, p_created_by_role character varying, p_affected_classroom_count integer, p_cancelled_session_count integer) RETURNS SETOF public.branch_closures
    LANGUAGE plpgsql
    AS $$
DECLARE v_id UUID;
BEGIN
    INSERT INTO branch_closures(
        tenant_id, organization_id, branch_id, status, reason, description,
        parent_announcement, effective_start_at, effective_end_at,
        created_by, created_by_role, affected_classroom_count, cancelled_session_count)
    VALUES (
        p_tenant_id, p_organization_id, p_branch_id, p_status, p_reason, p_description,
        p_parent_announcement, p_effective_start_at, p_effective_end_at,
        p_created_by, p_created_by_role, p_affected_classroom_count, p_cancelled_session_count)
    RETURNING id INTO v_id;

    IF p_effective_start_at <= now() THEN
        UPDATE branches
        SET operational_status = p_status, active_closure_id = v_id, updated_at = now()
        WHERE tenant_id = p_tenant_id AND id = p_branch_id;
    END IF;

    RETURN QUERY SELECT * FROM branch_closures WHERE id = v_id;
END;
$$;


--
-- Name: fn_create_child(uuid, uuid, character varying, character varying, timestamp with time zone, uuid, text, integer, character varying, text, boolean, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
