CREATE FUNCTION public.fn_create_user(p_id uuid, p_tenant_id uuid, p_email character varying, p_normalized_email character varying, p_password_hash character varying, p_first_name character varying, p_last_name character varying, p_display_name character varying, p_is_active boolean, p_created_at timestamp with time zone, p_updated_at timestamp with time zone) RETURNS TABLE(id uuid, tenant_id uuid, email character varying, first_name character varying, last_name character varying, display_name character varying, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    INSERT INTO users (id, tenant_id, email, normalized_email, password_hash, first_name, last_name, display_name, is_active, created_at, updated_at)
    VALUES (p_id, p_tenant_id, p_email, p_normalized_email, p_password_hash, p_first_name, p_last_name, p_display_name, p_is_active, p_created_at, p_updated_at)
    RETURNING users.id, users.tenant_id, users.email, users.first_name, users.last_name, users.display_name, users.is_active, users.created_at, users.updated_at;
END;
$$;


--
-- Name: fn_delete_org_qr_code(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_delete_org_qr_code(p_tenant_id uuid, p_organization_id uuid, p_slot_index integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM org_payment_qr_codes
    WHERE tenant_id = p_tenant_id AND organization_id = p_organization_id AND slot_index = p_slot_index;
    RETURN FOUND;
END;
$$;


--
-- Name: fn_delete_platform_experience(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_delete_platform_experience(p_id uuid) RETURNS TABLE(deleted boolean, blocking_reason text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM platform_experiences WHERE id = p_id) THEN
        RETURN QUERY SELECT false, 'Platform experience not found.'::text;
        RETURN;
    END IF;

    IF EXISTS (SELECT 1 FROM marketplace_orders WHERE platform_experience_id = p_id)
       OR EXISTS (SELECT 1 FROM organization_entitlements WHERE platform_experience_id = p_id) THEN
        RETURN QUERY SELECT false, 'This experience has existing organization orders or entitlements and cannot be deleted. Use Discontinue instead.'::text;
        RETURN;
    END IF;

    DELETE FROM platform_experiences WHERE id = p_id;
    RETURN QUERY SELECT true, NULL::text;
END;
$$;


--
-- Name: fn_dev_login(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_dev_login(p_email character varying DEFAULT NULL::character varying) RETURNS TABLE(out_status character varying, out_user_id uuid, out_tenant_id uuid, out_effective_tenant_id uuid, out_active_org_id uuid, out_email character varying, out_display_name character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_target_email VARCHAR;
BEGIN
    IF p_email IS NOT NULL AND TRIM(p_email) <> '' THEN
        SELECT email INTO v_target_email 
        FROM users 
        WHERE LOWER(email) = LOWER(TRIM(p_email)) OR normalized_email = UPPER(TRIM(p_email)) 
        LIMIT 1;
    END IF;

    IF v_target_email IS NULL THEN
        SELECT email INTO v_target_email 
        FROM users 
        WHERE normalized_email = 'PRIYA@LITTLESTARS.COM' 
        LIMIT 1;
    END IF;

    IF v_target_email IS NULL THEN
        SELECT email INTO v_target_email 
        FROM users 
        ORDER BY created_at ASC 
        LIMIT 1;
    END IF;

    IF v_target_email IS NULL THEN
        RETURN QUERY SELECT 'no_users'::VARCHAR, NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::VARCHAR, NULL::VARCHAR;
        RETURN;
    END IF;

    RETURN QUERY 
    SELECT * FROM fn_sync_external_login('DevLogin', v_target_email, v_target_email, 'Dev', 'User', NULL, 'Daycare');
END;
$$;


--
-- Name: fn_find_classroom_conflicts(uuid, uuid, date, time without time zone, time without time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_find_classroom_conflicts(p_tenant_id uuid, p_classroom_id uuid, p_date date, p_start time without time zone, p_end time without time zone, p_exclude_event_id uuid DEFAULT NULL::uuid) RETURNS TABLE(event_id uuid, title character varying, start_time time without time zone, end_time time without time zone, organizer_id uuid, organizer_name text)
    LANGUAGE sql STABLE
    AS $$
    SELECT e.id, e.title, e.start_time, e.end_time, e.organizer_id,
           COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')), ''), u.email)::text
    FROM events e
    JOIN event_classrooms ec ON ec.event_id = e.id
    LEFT JOIN users u ON u.id = e.organizer_id
    WHERE e.tenant_id = p_tenant_id
      AND ec.classroom_id = p_classroom_id
      AND e.event_date = p_date
      AND e.status <> 'Cancelled'
      AND (p_exclude_event_id IS NULL OR e.id <> p_exclude_event_id)
      AND COALESCE(e.start_time, '00:00'::time) < COALESCE(p_end, '23:59:59.999999'::time)
      AND COALESCE(e.end_time, '23:59:59.999999'::time) > COALESCE(p_start, '00:00'::time)
    ORDER BY e.start_time NULLS FIRST;
$$;


--
-- Name: fn_get_active_agent_webhooks_for_event(uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_active_agent_webhooks_for_event(p_tenant_id uuid, p_event_type character varying) RETURNS TABLE(id uuid, tenant_id uuid, user_id uuid, name character varying, webhook_url text, secret_key character varying, subscribed_events text[], is_active boolean, last_triggered_at timestamp with time zone, failure_count integer, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT w.id, w.tenant_id, w.user_id, w.name, w.webhook_url, w.secret_key,
           w.subscribed_events, w.is_active, w.last_triggered_at, w.failure_count,
           w.created_at, w.updated_at
    FROM agent_webhook_subscriptions w
    WHERE w.tenant_id = p_tenant_id 
      AND w.is_active = TRUE
      AND (p_event_type = ANY(w.subscribed_events) OR '*' = ANY(w.subscribed_events));
$$;


--
-- Name: fn_get_active_branch_closure(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_active_branch_closure(p_tenant_id uuid, p_branch_id uuid, p_at_time timestamp with time zone) RETURNS SETOF public.branch_closures
    LANGUAGE sql STABLE
    AS $$
SELECT * FROM branch_closures
WHERE tenant_id = p_tenant_id
  AND branch_id = p_branch_id
  AND reopened_at IS NULL
  AND effective_start_at <= p_at_time
  AND (effective_end_at IS NULL OR effective_end_at > p_at_time)
ORDER BY effective_start_at DESC
LIMIT 1;
$$;


--
-- Name: fn_get_active_child_care_plan(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_active_child_care_plan(p_tenant_id uuid, p_child_id uuid) RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, child_id uuid, version integer, diaper_routine_guidance text, feeding_instructions text, bottle_schedule_guidance text, sleep_routine_guidance text, toileting_support_plan text, comfort_calming_preferences text, required_supplies_note text, dietary_allergies_summary text, effective_date date, review_date date, status character varying, created_by_user_id uuid, approved_by_user_id uuid, approved_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, child_name text)
    LANGUAGE sql STABLE
    AS $$
    SELECT p.id, p.tenant_id, p.organization_id, p.branch_id, p.child_id, p.version,
           p.diaper_routine_guidance, p.feeding_instructions, p.bottle_schedule_guidance,
           p.sleep_routine_guidance, p.toileting_support_plan, p.comfort_calming_preferences,
           p.required_supplies_note, p.dietary_allergies_summary, p.effective_date, p.review_date,
           p.status, p.created_by_user_id, p.approved_by_user_id, p.approved_at, p.created_at, p.updated_at,
           CONCAT(c.first_name, ' ', c.last_name) AS child_name
    FROM child_care_plans p
    JOIN children c ON p.child_id = c.id
    WHERE p.tenant_id = p_tenant_id 
      AND p.child_id = p_child_id 
      AND p.status = 'Active'
    ORDER BY p.version DESC
    LIMIT 1;
$$;


