    RETURN QUERY
    SELECT u.id, u.tenant_id, u.email, u.first_name, u.last_name, u.display_name, u.is_active, u.created_at, u.updated_at
    FROM users u
    WHERE u.tenant_id = p_tenant_id
    ORDER BY u.first_name, u.last_name;
END;
$$;


