--
-- Name: fn_get_branch_closure_history(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_branch_closure_history(p_tenant_id uuid, p_organization_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid) RETURNS SETOF public.branch_closures
    LANGUAGE sql STABLE
    AS $$
SELECT * FROM branch_closures
WHERE tenant_id = p_tenant_id
  AND (p_organization_id IS NULL OR organization_id = p_organization_id)
  AND (p_branch_id IS NULL OR branch_id = p_branch_id)
ORDER BY effective_start_at DESC;
$$;


--
-- Name: fn_get_branch_daily_status(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_branch_daily_status(p_tenant_id uuid, p_branch_id uuid, p_date date) RETURNS TABLE(branch_id uuid, operation_date date, status character varying, opened_at timestamp with time zone, opened_by_name character varying, closed_at timestamp with time zone, closed_by_name character varying, total_classrooms integer, open_classrooms integer, closed_classrooms integer, pending_children_count integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH b_op AS (
        SELECT 
            bdo.status,
            bdo.opened_at,
            (u_open.first_name || ' ' || u_open.last_name)::VARCHAR AS opened_by_name,
            bdo.closed_at,
            (u_close.first_name || ' ' || u_close.last_name)::VARCHAR AS closed_by_name
        FROM public.branch_daily_operations bdo
        LEFT JOIN public.users u_open ON bdo.opened_by_user_id = u_open.id
        LEFT JOIN public.users u_close ON bdo.closed_by_user_id = u_close.id
        WHERE bdo.tenant_id = p_tenant_id AND bdo.branch_id = p_branch_id AND bdo.operation_date = p_date
    ),
    rooms AS (
        SELECT 
            COUNT(c.id)::INT AS total_count,
            COUNT(CASE WHEN cdo.status = 'Open' THEN 1 END)::INT AS open_count,
            COUNT(CASE WHEN cdo.status = 'Closed' THEN 1 END)::INT AS closed_count
        FROM public.classrooms c
        LEFT JOIN public.classroom_daily_operations cdo 
          ON c.id = cdo.classroom_id 
         AND cdo.tenant_id = p_tenant_id 
         AND cdo.operation_date = p_date
        WHERE c.branch_id = p_branch_id AND c.is_active = TRUE
    ),
    pending_kids AS (
        SELECT COUNT(ca.id)::INT AS cnt
        FROM public.child_attendance ca
        WHERE ca.tenant_id = p_tenant_id
          AND ca.branch_id = p_branch_id
          AND ca.attendance_date = p_date
          AND ca.status = 'Present'
          AND ca.departure_time IS NULL
    )
    SELECT 
        p_branch_id,
        p_date,
        COALESCE((SELECT b_op.status FROM b_op), 'Closed'::VARCHAR(20)),
        (SELECT b_op.opened_at FROM b_op),
        (SELECT b_op.opened_by_name FROM b_op),
        (SELECT b_op.closed_at FROM b_op),
        (SELECT b_op.closed_by_name FROM b_op),
        COALESCE((SELECT rooms.total_count FROM rooms), 0),
        COALESCE((SELECT rooms.open_count FROM rooms), 0),
        COALESCE((SELECT rooms.closed_count FROM rooms), 0),
        COALESCE((SELECT pending_kids.cnt FROM pending_kids), 0);
END;
$$;


--
-- Name: fn_get_branch_enrolled_children_count(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
