--
-- Name: fn_get_child_guardians_for_admin(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_child_guardians_for_admin(p_tenant_id uuid, p_child_id uuid) RETURNS TABLE(person_id uuid, user_id uuid, first_name character varying, last_name character varying, email character varying, phone character varying, relationship character varying, is_primary boolean, can_pickup boolean, has_portal_access boolean, status character varying, verified_at timestamp with time zone, revoked_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        p.id AS person_id,
        p.user_id,
        p.first_name::VARCHAR,
        p.last_name::VARCHAR,
        COALESCE(p.email, u.email, '')::VARCHAR AS email,
        COALESCE(p.mobile_phone, p.alternate_phone, '')::VARCHAR AS phone,
        cg.relationship::VARCHAR,
        cg.is_primary,
        cg.can_pickup,
        (fr.id IS NOT NULL AND fr.status = 'Verified' AND fr.revoked_at IS NULL) AS has_portal_access,
        COALESCE(fr.status, 'Pending')::VARCHAR AS status,
        fr.verified_at,
        fr.revoked_at
    FROM public.child_guardians cg
    JOIN public.persons p ON cg.person_id = p.id
    LEFT JOIN public.users u ON p.user_id = u.id
    LEFT JOIN public.family_relationships fr ON fr.child_id = cg.child_id AND fr.user_id = p.user_id
    WHERE cg.tenant_id = p_tenant_id 
      AND cg.child_id = p_child_id
    ORDER BY cg.is_primary DESC, p.first_name, p.last_name;
END;
$$;


--
-- Name: fn_get_child_interests_by_child_id(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_child_interests_by_child_id(p_tenant_id uuid, p_child_id uuid) RETURNS TABLE(id uuid, tenant_id uuid, child_id uuid, name character varying, created_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT ci.id, ci.tenant_id, ci.child_id, ci.name, ci.created_at
    FROM child_interests ci
    WHERE ci.child_id = p_child_id AND ci.tenant_id = p_tenant_id
    ORDER BY ci.created_at DESC;
END;
$$;


--
-- Name: fn_get_child_invoices(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_child_invoices(p_tenant_id uuid, p_child_id uuid) RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, child_id uuid, contract_id uuid, invoice_number character varying, billing_period character varying, subtotal numeric, discount_amount numeric, tax_amount numeric, total_amount numeric, amount_paid numeric, adjustment_amount numeric, pending_verification_amount numeric, currency character varying, status character varying, fee_method character varying, fee_plan_name character varying, issue_date timestamp with time zone, due_date timestamp with time zone, paid_at timestamp with time zone, description text, notes text, payment_instructions text, payment_instructions_snapshot jsonb, billing_contact_email character varying, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT
        i.id, i.tenant_id, i.organization_id, i.branch_id, i.child_id, i.contract_id,
        i.invoice_number, i.billing_period, i.subtotal, i.discount_amount, i.tax_amount,
        i.total_amount, i.amount_paid, COALESCE(i.adjustment_amount, 0),
        COALESCE(i.pending_verification_amount, 0), i.currency, i.status,
        i.fee_method, i.fee_plan_name, i.issue_date, i.due_date, i.paid_at,
        i.description, i.notes, i.payment_instructions, i.payment_instructions_snapshot,
        i.billing_contact_email, i.created_at, i.updated_at
    FROM invoices i
    WHERE i.tenant_id = p_tenant_id
      AND i.child_id = p_child_id
      AND i.status <> 'Draft'
    ORDER BY i.issue_date DESC;
$$;


