--
-- Name: fn_get_classroom_daily_status(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_classroom_daily_status(p_tenant_id uuid, p_classroom_id uuid, p_date date) RETURNS TABLE(classroom_id uuid, branch_id uuid, operation_date date, status character varying, opened_at timestamp with time zone, opened_by_name character varying, closed_at timestamp with time zone, closed_by_name character varying, branch_status character varying, active_children_count integer, active_activities_count integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_branch_id UUID;
BEGIN
    SELECT c.branch_id INTO v_branch_id
    FROM public.classrooms c
    WHERE c.id = p_classroom_id;

    RETURN QUERY
    WITH c_op AS (
        SELECT 
            cdo.status,
            cdo.opened_at,
            (u_open.first_name || ' ' || u_open.last_name)::VARCHAR AS opened_by_name,
            cdo.closed_at,
            (u_close.first_name || ' ' || u_close.last_name)::VARCHAR AS closed_by_name
        FROM public.classroom_daily_operations cdo
        LEFT JOIN public.users u_open ON cdo.opened_by_user_id = u_open.id
        LEFT JOIN public.users u_close ON cdo.closed_by_user_id = u_close.id
        WHERE cdo.tenant_id = p_tenant_id AND cdo.classroom_id = p_classroom_id AND cdo.operation_date = p_date
    ),
    b_op AS (
        SELECT bdo.status
        FROM public.branch_daily_operations bdo
        WHERE bdo.tenant_id = p_tenant_id AND bdo.branch_id = v_branch_id AND bdo.operation_date = p_date
    ),
    active_kids AS (
        SELECT COUNT(ca.id)::INT AS cnt
        FROM public.child_attendance ca
        WHERE ca.tenant_id = p_tenant_id
          AND ca.classroom_id = p_classroom_id
          AND ca.attendance_date = p_date
          AND ca.status = 'Present'
          AND ca.departure_time IS NULL
    ),
    active_act AS (
        SELECT COUNT(es.id)::INT AS cnt
        FROM public.experience_sessions es
        WHERE es.tenant_id = p_tenant_id
          AND es.classroom_id = p_classroom_id
          AND es.session_date = p_date
          AND es.status IN ('InProgress', 'Active', 'Planned')
    )
    SELECT 
        p_classroom_id,
        v_branch_id,
        p_date,
        COALESCE((SELECT c_op.status FROM c_op), 'Closed'::VARCHAR(20)),
        (SELECT c_op.opened_at FROM c_op),
        (SELECT c_op.opened_by_name FROM c_op),
        (SELECT c_op.closed_at FROM c_op),
        (SELECT c_op.closed_by_name FROM c_op),
        COALESCE((SELECT b_op.status FROM b_op), 'Closed'::VARCHAR(20)),
        COALESCE((SELECT active_kids.cnt FROM active_kids), 0),
        COALESCE((SELECT active_act.cnt FROM active_act), 0);
END;
$$;


--
-- Name: fn_get_classroom_memories(uuid, uuid, timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_classroom_memories(p_tenant_id uuid, p_classroom_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, tenant_id uuid, event_date timestamp with time zone, event_type character varying, title character varying, description text, source_id uuid, source_type character varying, child_id uuid, classroom_id uuid, teacher_id uuid, experience_id uuid)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT * FROM (
        SELECT 
            je.id, je.tenant_id, je.observation_date AS event_date,
            'Observation'::VARCHAR AS event_type,
            COALESCE(je.title, 'Journey Entry')::VARCHAR AS title,
            je.observation AS description,
            je.id AS source_id,
            'child_journey_entries'::VARCHAR AS source_type,
            je.child_id,
            je.classroom_id,
            je.teacher_id,
            je.experience_id
        FROM child_journey_entries je
        WHERE je.tenant_id = p_tenant_id AND je.classroom_id = p_classroom_id

        UNION ALL

        SELECT 
            s.id, s.tenant_id,
            (s.session_date + COALESCE(s.end_time, s.start_time, '00:00:00'::TIME))::TIMESTAMPTZ AS event_date,
            'Session'::VARCHAR AS event_type,
            'Experience Session'::VARCHAR AS title,
            s.actual_notes AS description,
            s.id AS source_id,
            'experience_sessions'::VARCHAR AS source_type,
            NULL::UUID AS child_id,
            s.classroom_id,
            s.primary_teacher_id AS teacher_id,
            s.experience_id
        FROM experience_sessions s
        WHERE s.tenant_id = p_tenant_id AND s.classroom_id = p_classroom_id

        UNION ALL

        SELECT 
            f.id, f.tenant_id,
            f.created_at AS event_date,
            'Feedback'::VARCHAR AS event_type,
            'Teacher Feedback'::VARCHAR AS title,
            f.notes AS description,
            f.id AS source_id,
            'experience_feedbacks'::VARCHAR AS source_type,
            NULL::UUID AS child_id,
            s.classroom_id,
            f.teacher_id,
            s.experience_id
        FROM experience_feedback f
        JOIN experience_schedules s ON f.experience_schedule_id = s.id
        WHERE f.tenant_id = p_tenant_id AND s.classroom_id = p_classroom_id
    ) AS combined
    WHERE (p_start_date IS NULL OR combined.event_date >= p_start_date)
      AND (p_end_date IS NULL OR combined.event_date <= p_end_date)
    ORDER BY combined.event_date DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: fn_get_classroom_peers_for_gifting(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_classroom_peers_for_gifting(p_tenant_id uuid, p_classroom_id uuid, p_exclude_child_id uuid DEFAULT NULL::uuid) RETURNS TABLE(child_id uuid, first_name character varying, last_name character varying, date_of_birth date, photo_url text, classroom_id uuid, is_birthday_today boolean, is_birthday_this_month boolean)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        c.id AS child_id,
        c.first_name,
        c.last_name,
        c.date_of_birth,
        c.photo_url,
        c.classroom_id,
        (EXTRACT(MONTH FROM c.date_of_birth) = EXTRACT(MONTH FROM CURRENT_DATE) AND 
         EXTRACT(DAY FROM c.date_of_birth) = EXTRACT(DAY FROM CURRENT_DATE)) AS is_birthday_today,
        (EXTRACT(MONTH FROM c.date_of_birth) = EXTRACT(MONTH FROM CURRENT_DATE)) AS is_birthday_this_month
    FROM children c
    WHERE c.tenant_id = p_tenant_id
      AND c.classroom_id = p_classroom_id
      AND c.is_active = TRUE
      AND (p_exclude_child_id IS NULL OR c.id <> p_exclude_child_id)
    ORDER BY is_birthday_today DESC, is_birthday_this_month DESC, c.first_name, c.last_name;
END;
$$;


