--
-- Name: fn_get_gifting_orders_for_admin(uuid, uuid, uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_gifting_orders_for_admin(p_tenant_id uuid, p_organization_id uuid, p_branch_id uuid DEFAULT NULL::uuid, p_classroom_id uuid DEFAULT NULL::uuid, p_status_filter character varying DEFAULT NULL::character varying) RETURNS TABLE(id uuid, order_number character varying, tenant_id uuid, organization_id uuid, branch_id uuid, classroom_id uuid, parent_user_id uuid, parent_email character varying, parent_name character varying, child_id uuid, recipient_type character varying, recipient_child_id uuid, recipient_child_name character varying, greeting_message text, delivery_destination_type character varying, confirmed_delivery_address text, confirmed_contact_name character varying, confirmed_contact_phone character varying, total_amount numeric, currency character varying, approval_status character varying, approval_decided_by_name character varying, approval_decided_at timestamp with time zone, rejection_reason text, payment_method character varying, payment_status character varying, fulfilment_status character varying, prepared_by_name character varying, prepared_at timestamp with time zone, received_by_name character varying, received_at timestamp with time zone, distributed_by_name character varying, distributed_at timestamp with time zone, distribution_notes text, completed_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        o.id, o.order_number, o.tenant_id, o.organization_id, o.branch_id, o.classroom_id,
        o.parent_user_id, o.parent_email, o.parent_name, o.child_id, o.recipient_type,
        o.recipient_child_id, o.recipient_child_name, o.greeting_message,
        o.delivery_destination_type, o.confirmed_delivery_address, o.confirmed_contact_name,
        o.confirmed_contact_phone, o.total_amount, o.currency, o.approval_status,
        o.approval_decided_by_name, o.approval_decided_at, o.rejection_reason,
        o.payment_method, o.payment_status, o.fulfilment_status, o.prepared_by_name,
        o.prepared_at, o.received_by_name, o.received_at, o.distributed_by_name,
        o.distributed_at, o.distribution_notes, o.completed_at, o.created_at, o.updated_at
    FROM classroom_gifting_orders o
    WHERE o.tenant_id = p_tenant_id
      AND o.organization_id = p_organization_id
      AND (p_branch_id IS NULL OR o.branch_id = p_branch_id)
      AND (p_classroom_id IS NULL OR o.classroom_id = p_classroom_id)
      AND (p_status_filter IS NULL OR p_status_filter = 'All' OR 
           o.approval_status = p_status_filter OR 
           o.payment_status = p_status_filter OR 
           o.fulfilment_status = p_status_filter)
    ORDER BY o.created_at DESC;
$$;


--
-- Name: fn_get_gifting_orders_for_parent(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_gifting_orders_for_parent(p_tenant_id uuid, p_parent_user_id uuid) RETURNS TABLE(id uuid, order_number character varying, organization_id uuid, branch_id uuid, classroom_id uuid, child_id uuid, recipient_type character varying, recipient_child_name character varying, greeting_message text, delivery_destination_type character varying, confirmed_delivery_address text, total_amount numeric, currency character varying, approval_status character varying, rejection_reason text, payment_method character varying, payment_status character varying, fulfilment_status character varying, distributed_at timestamp with time zone, completed_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        o.id, o.order_number, o.organization_id, o.branch_id, o.classroom_id, o.child_id,
        o.recipient_type, o.recipient_child_name, o.greeting_message,
        o.delivery_destination_type, o.confirmed_delivery_address, o.total_amount,
        o.currency, o.approval_status, o.rejection_reason, o.payment_method,
        o.payment_status, o.fulfilment_status, o.distributed_at, o.completed_at, o.created_at
    FROM classroom_gifting_orders o
    WHERE o.tenant_id = p_tenant_id
      AND o.parent_user_id = p_parent_user_id
    ORDER BY o.created_at DESC;
$$;


--
-- Name: fn_get_harvest_monthly_metrics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_harvest_monthly_metrics(p_tenant_id uuid) RETURNS TABLE(total_experiences integer, total_feedbacks integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        (SELECT COUNT(*)::INT 
         FROM experience_schedules es 
         WHERE es.tenant_id = p_tenant_id 
           AND EXTRACT(MONTH FROM es.scheduled_date) = EXTRACT(MONTH FROM CURRENT_DATE) 
           AND EXTRACT(YEAR FROM es.scheduled_date) = EXTRACT(YEAR FROM CURRENT_DATE)) AS total_experiences,
        (SELECT COUNT(*)::INT 
         FROM experience_feedback f
         JOIN experience_schedules s ON f.experience_schedule_id = s.id
         WHERE f.tenant_id = p_tenant_id 
           AND EXTRACT(MONTH FROM s.scheduled_date) = EXTRACT(MONTH FROM CURRENT_DATE) 
           AND EXTRACT(YEAR FROM s.scheduled_date) = EXTRACT(YEAR FROM CURRENT_DATE)) AS total_feedbacks;
END;
$$;


--
-- Name: fn_get_harvest_performance_items(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_harvest_performance_items(p_tenant_id uuid) RETURNS TABLE(experience_id uuid, title character varying, subtitle text, uses integer, response text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        e.id AS experience_id,
        e.title,
        ('Created by ' || COALESCE((SELECT u.first_name FROM users u WHERE u.id = e.created_by_user_id), 'Educator'))::TEXT AS subtitle,
        (SELECT COUNT(*)::INT FROM experience_schedules es WHERE es.experience_id = e.id) AS uses,
        ('💬 ' || (SELECT COUNT(1) FROM experience_feedback f JOIN experience_schedules s ON f.experience_schedule_id = s.id WHERE s.experience_id = e.id))::TEXT AS response
    FROM experiences e
    WHERE e.tenant_id = p_tenant_id AND e.status NOT IN ('Idea', 'Draft', 'Archived')
    ORDER BY uses DESC
    LIMIT 10;
END;
$$;


--
-- Name: fn_get_intelligence_curriculum_variety(uuid, uuid, uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_intelligence_curriculum_variety(p_tenant_id uuid, p_org_id uuid, p_branch_id uuid, p_classroom_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(title character varying, usage_count bigint)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        e.title AS title,
        COUNT(es.id) AS usage_count
    FROM experience_schedules es
    JOIN experiences e ON es.experience_id = e.id
    JOIN classrooms cl ON es.classroom_id = cl.id
    JOIN branches b ON cl.branch_id = b.id
    WHERE es.tenant_id = p_tenant_id
      AND b.organization_id = p_org_id
      AND (p_branch_id IS NULL OR b.id = p_branch_id)
      AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)
      AND es.scheduled_date BETWEEN p_start_date AND p_end_date
    GROUP BY e.title
    ORDER BY usage_count DESC;
$$;


