--
-- Name: invoice_installments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.invoice_installments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    invoice_id uuid NOT NULL,
    installment_number integer NOT NULL,
    due_date date NOT NULL,
    amount_due numeric(14,2) NOT NULL,
    allow_custom_amount boolean DEFAULT true NOT NULL,
    allow_multiple_transactions boolean DEFAULT true NOT NULL,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT invoice_installments_amount_due_check CHECK ((amount_due > (0)::numeric))
);


--
-- Name: fn_get_invoice_installments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_invoice_installments(p_invoice_id uuid) RETURNS SETOF public.invoice_installments
    LANGUAGE sql STABLE
    AS $$
    SELECT * FROM invoice_installments WHERE invoice_id = p_invoice_id ORDER BY installment_number ASC;
$$;


