--
-- Name: fn_get_org_admin_email_for_org(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_org_admin_email_for_org(p_organization_id uuid) RETURNS TABLE(user_id uuid, email character varying, display_name character varying)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        u.id AS user_id,
        u.email::VARCHAR,
        COALESCE(u.display_name, u.first_name || ' ' || u.last_name, u.email)::VARCHAR AS display_name
    FROM public.user_organization_roles uor
    JOIN public.users u ON uor.user_id = u.id
    JOIN public.roles r ON uor.role_id = r.id
    WHERE uor.organization_id = p_organization_id 
      AND (r.name = 'OrganizationAdmin' OR r.name = 'OrgAdmin')
      AND u.is_active = TRUE
    ORDER BY u.created_at ASC
    LIMIT 1;
$$;


