CREATE FUNCTION public.fn_get_org_fee_plans(p_tenant_id uuid, p_organization_id uuid) RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, name character varying, description text, fee_category character varying, billing_frequency character varying, currency character varying, is_active boolean, allow_partial_payment boolean, minimum_partial_payment numeric, allow_parent_cash_declaration boolean, created_by character varying, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT id, tenant_id, organization_id, name, description,
           fee_category, billing_frequency, currency, is_active,
           allow_partial_payment, minimum_partial_payment,
           allow_parent_cash_declaration, created_by, created_at, updated_at
    FROM org_fee_plans
    WHERE tenant_id = p_tenant_id AND organization_id = p_organization_id
