    slot_index integer NOT NULL,
    display_name character varying(150) NOT NULL,
    payment_purpose character varying(200),
    qr_image_data_uri text NOT NULL,
    instructions text,
    is_active boolean DEFAULT true NOT NULL,
    updated_by character varying(200),
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT org_payment_qr_codes_slot_index_check CHECK (((slot_index >= 1) AND (slot_index <= 3)))
);


--
-- Name: fn_get_org_qr_codes(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_org_qr_codes(p_tenant_id uuid, p_organization_id uuid) RETURNS SETOF public.org_payment_qr_codes
    LANGUAGE sql STABLE
    AS $$
    SELECT * FROM org_payment_qr_codes
    WHERE tenant_id = p_tenant_id AND organization_id = p_organization_id
    ORDER BY slot_index ASC;
$$;


--
-- Name: fn_get_org_tariff_rules(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_org_tariff_rules(p_tenant_id uuid, p_organization_id uuid, p_fee_plan_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, fee_plan_id uuid, plan_name character varying, billing_frequency character varying, fee_category character varying, scope_type character varying, branch_id uuid, branch_name character varying, classroom_id uuid, classroom_name character varying, child_id uuid, child_name text, location_tier character varying, child_category character varying, amount numeric, currency character varying, effective_date date, expiry_date date, is_active boolean, notes text, created_by character varying, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT
        r.id, r.tenant_id, r.organization_id, r.fee_plan_id,
        p.name AS plan_name, p.billing_frequency, p.fee_category,
        r.scope_type, r.branch_id, b.name AS branch_name,
        r.classroom_id, cl.name AS classroom_name,
        r.child_id, TRIM(CONCAT(ch.first_name, ' ', ch.last_name)) AS child_name,
        r.location_tier, r.child_category,
        r.amount, r.currency, r.effective_date, r.expiry_date,
        r.is_active, r.notes, r.created_by, r.created_at, r.updated_at
    FROM org_tariff_rules r
    INNER JOIN org_fee_plans p ON p.id = r.fee_plan_id
    LEFT JOIN branches b ON b.id = r.branch_id
    LEFT JOIN classrooms cl ON cl.id = r.classroom_id
    LEFT JOIN children ch ON ch.id = r.child_id
    WHERE r.tenant_id = p_tenant_id
      AND r.organization_id = p_organization_id
      AND (p_fee_plan_id IS NULL OR r.fee_plan_id = p_fee_plan_id)
    ORDER BY
        CASE r.scope_type
            WHEN 'Child' THEN 1
            WHEN 'Classroom' THEN 2
            WHEN 'Branch' THEN 3
            WHEN 'LocationTier' THEN 4
            ELSE 5
        END,
        r.effective_date DESC;
$$;


--
-- Name: fn_get_org_tuition_invoices(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_org_tuition_invoices(p_tenant_id uuid, p_organization_id uuid, p_branch_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, child_id uuid, contract_id uuid, child_name text, branch_name text, invoice_number character varying, billing_period character varying, subtotal numeric, discount_amount numeric, tax_amount numeric, total_amount numeric, amount_paid numeric, adjustment_amount numeric, pending_verification_amount numeric, currency character varying, status character varying, fee_method character varying, fee_plan_name character varying, issue_date timestamp with time zone, due_date timestamp with time zone, paid_at timestamp with time zone, description text, notes text, payment_instructions text, payment_instructions_snapshot jsonb, billing_contact_email character varying, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT
        i.id, i.tenant_id, i.organization_id, i.branch_id, i.child_id, i.contract_id,
        COALESCE(TRIM(CONCAT(c.first_name, ' ', c.last_name)), 'Child Record') AS child_name,
        COALESCE(b.name, 'Organization Wide') AS branch_name,
        i.invoice_number, i.billing_period, i.subtotal, i.discount_amount, i.tax_amount,
        i.total_amount, i.amount_paid, COALESCE(i.adjustment_amount, 0),
        COALESCE(i.pending_verification_amount, 0), i.currency, i.status,
        i.fee_method, i.fee_plan_name, i.issue_date, i.due_date, i.paid_at,
        i.description, i.notes, i.payment_instructions, i.payment_instructions_snapshot,
        i.billing_contact_email, i.created_at, i.updated_at
    FROM invoices i
    LEFT JOIN children c ON c.id = i.child_id
    LEFT JOIN branches b ON b.id = i.branch_id
    WHERE i.tenant_id = p_tenant_id
      AND i.organization_id = p_organization_id
      AND i.child_id IS NOT NULL
      AND (p_branch_id IS NULL OR i.branch_id = p_branch_id)
    ORDER BY i.issue_date DESC;
$$;


--
-- Name: fn_get_organization_billing_settings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_organization_billing_settings(p_organization_id uuid) RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, mode character varying, frequency character varying, effective_date timestamp with time zone, next_billing_date timestamp with time zone, auto_charge_enabled boolean, notes text, updated_by character varying, updated_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        id, tenant_id, organization_id, mode, frequency, effective_date,
        next_billing_date, auto_charge_enabled, notes, updated_by, updated_at
    FROM organization_billing_settings
    WHERE organization_id = p_organization_id;
$$;


--
-- Name: fn_get_organization_by_id(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_organization_by_id(p_tenant_id uuid, p_id uuid) RETURNS TABLE(id uuid, tenant_id uuid, name character varying, location character varying, is_active boolean, account_status character varying, suspension_reason text, created_at timestamp with time zone, updated_at timestamp with time zone, currency character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT o.id, o.tenant_id, o.name, o.location, o.is_active,
           COALESCE(o.account_status, CASE WHEN o.is_active THEN 'Active' ELSE 'Suspended' END)::varchar,
           o.suspension_reason, o.created_at, o.updated_at,
           COALESCE(o.currency, 'INR')::varchar AS currency
    FROM organizations o
    WHERE o.tenant_id = p_tenant_id AND o.id = p_id;
END;
$$;


--
-- Name: fn_get_organization_by_id_global(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_organization_by_id_global(p_id uuid) RETURNS TABLE(id uuid, tenant_id uuid, name character varying, location character varying, is_active boolean, account_status character varying, suspension_reason text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT o.id, o.tenant_id, o.name, o.location, o.is_active,
           COALESCE(o.account_status, CASE WHEN o.is_active THEN 'Active' ELSE 'Suspended' END)::varchar,
           o.suspension_reason,
           o.created_at, o.updated_at
    FROM organizations o
    WHERE o.id = p_id;
END;
$$;


--
-- Name: fn_get_organization_entitlement(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_organization_entitlement(p_organization_id uuid, p_platform_experience_id uuid) RETURNS SETOF public.organization_entitlements
    LANGUAGE sql STABLE
    AS $$
    SELECT *
    FROM organization_entitlements
    WHERE organization_id = p_organization_id AND platform_experience_id = p_platform_experience_id
      AND status = 'Active' AND (expires_at IS NULL OR expires_at > NOW());
$$;


--
-- Name: fn_get_organization_entitlements(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_organization_entitlements(p_organization_id uuid) RETURNS SETOF public.organization_entitlements
    LANGUAGE sql STABLE
    AS $$
    SELECT *
    FROM organization_entitlements
    WHERE organization_id = p_organization_id AND status = 'Active'
      AND (expires_at IS NULL OR expires_at > NOW())
    ORDER BY granted_at DESC;
$$;


--
-- Name: fn_get_organization_hierarchy(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_organization_hierarchy(p_tenant_id uuid, p_org_id uuid, p_requesting_user_id uuid, p_is_org_admin boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_org record;
    v_org_admins jsonb;
    v_org_admin_ids uuid[];
    v_branches jsonb;
    v_total_staff int := 0;
    v_total_students int := 0;
BEGIN
    -- 1. Fetch organization details
    SELECT id, name, location, COALESCE(currency, 'INR') AS currency
    INTO v_org
    FROM organizations
    WHERE id = p_org_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('OrganizationId', p_org_id, 'Currency', 'INR');
    END IF;

    -- 2. Fetch Organization Admins (and capture their IDs once for staff count)
    SELECT
        COALESCE(jsonb_agg(
            jsonb_build_object(
                'UserId', oa.id,
                'Name', oa.display_name,
                'Email', oa.email,
                'RoleName', 'Organization Admin'
            ) ORDER BY oa.display_name
        ), '[]'::jsonb),
        COALESCE(array_agg(oa.id), ARRAY[]::uuid[])
    INTO v_org_admins, v_org_admin_ids
    FROM (
        SELECT DISTINCT ON (u.id)
            u.id,
            COALESCE(NULLIF(TRIM(u.display_name), ''), TRIM(u.first_name || ' ' || u.last_name), u.email) AS display_name,
            u.email
        FROM users u
        JOIN user_organization_roles uor ON uor.user_id = u.id AND uor.organization_id = p_org_id
        JOIN roles r ON uor.role_id = r.id
        WHERE r.name IN ('OrganizationAdmin', 'OrganizationOwner', 'SuperAdmin')
    ) oa;

    -- 3. Fetch Authorized Branches, their hierarchy, and totals in a single materialized pass
    WITH authorized_branches AS MATERIALIZED (
        SELECT b.id, b.name, b.location
        FROM branches b
        WHERE b.organization_id = p_org_id
          AND b.is_active = true
          AND (
              p_is_org_admin = true
              OR EXISTS (
                  SELECT 1 FROM user_branch_assignments uba
                  WHERE uba.branch_id = b.id
                    AND uba.user_id = p_requesting_user_id
                    AND uba.revoked_at IS NULL
              )
          )
        ORDER BY b.name
    ),
    lead_teacher_users AS MATERIALIZED (
        SELECT DISTINCT uor.user_id
        FROM user_organization_roles uor
        JOIN roles r ON uor.role_id = r.id
        WHERE (uor.organization_id = p_org_id OR uor.tenant_id = p_tenant_id)
          AND r.name IN ('LeadTeacher', 'Lead Teacher')
    ),
    branch_admins_cte AS MATERIALIZED (
        SELECT DISTINCT ON (uba.branch_id, u.id)
            uba.branch_id,
            u.id AS user_id,
            COALESCE(NULLIF(TRIM(u.display_name), ''), TRIM(u.first_name || ' ' || u.last_name), u.email) AS name,
            u.email
        FROM user_branch_assignments uba
        JOIN users u ON uba.user_id = u.id
        JOIN user_organization_roles uor ON uor.user_id = uba.user_id AND uor.organization_id = uba.organization_id
        JOIN roles r ON uor.role_id = r.id AND r.name = 'BranchAdmin'
        WHERE uba.branch_id IN (SELECT id FROM authorized_branches)
          AND uba.revoked_at IS NULL
        ORDER BY uba.branch_id, u.id, name
    ),
    branch_classrooms_cte AS MATERIALIZED (
        SELECT
            c.id, c.branch_id, c.name, c.code AS room_number, COALESCE(c.capacity, 0) AS capacity
        FROM classrooms c
        WHERE c.branch_id IN (SELECT id FROM authorized_branches)
          AND c.is_active = true
        ORDER BY c.name
    ),
    classroom_teachers_cte AS MATERIALIZED (
        SELECT
            ct.classroom_id,
            u.id AS user_id,
            COALESCE(NULLIF(TRIM(u.display_name), ''), TRIM(u.first_name || ' ' || u.last_name), u.email) AS name,
            u.email,
            (ct.is_primary OR ltu.user_id IS NOT NULL) AS is_lead,
            CASE
                WHEN (ct.is_primary OR ltu.user_id IS NOT NULL) THEN 'Lead Teacher'
                ELSE 'Educator'
            END AS role_name
        FROM classroom_teachers ct
        JOIN users u ON ct.user_id = u.id
        LEFT JOIN lead_teacher_users ltu ON ltu.user_id = u.id
        WHERE ct.classroom_id IN (SELECT id FROM branch_classrooms_cte)
        ORDER BY is_lead DESC, name
    ),
    first_classroom_teacher AS MATERIALIZED (
        SELECT DISTINCT ON (classroom_id)
            classroom_id,
            name AS assigned_teacher_name
        FROM classroom_teachers_cte
        ORDER BY classroom_id, is_lead DESC, name
    ),
    classroom_children_cte AS MATERIALIZED (
        SELECT
            ch.id AS child_id,
            ch.classroom_id,
            TRIM(ch.first_name || ' ' || ch.last_name) AS full_name,
            ch.photo_url
        FROM children ch
        WHERE ch.classroom_id IN (SELECT id FROM branch_classrooms_cte)
          AND ch.is_active = true
          AND (ch.enrollment_status IS NULL OR ch.enrollment_status != 'Withdrawn')
        ORDER BY ch.first_name, ch.last_name
    ),
    unassigned_branch_staff_cte AS MATERIALIZED (
        SELECT DISTINCT ON (uba.branch_id, u.id)
            uba.branch_id,
            u.id AS user_id,
            COALESCE(NULLIF(TRIM(u.display_name), ''), TRIM(u.first_name || ' ' || u.last_name), u.email) AS name,
            u.email,
            CASE
                WHEN ltu.user_id IS NOT NULL THEN 'Lead Teacher'
                ELSE 'Educator'
            END AS role_name
        FROM user_branch_assignments uba
        JOIN users u ON uba.user_id = u.id
        LEFT JOIN lead_teacher_users ltu ON ltu.user_id = u.id
        WHERE uba.branch_id IN (SELECT id FROM authorized_branches)
          AND uba.revoked_at IS NULL
          AND NOT EXISTS (
              SELECT 1 FROM classroom_teachers ct
              JOIN classrooms c ON ct.classroom_id = c.id
              WHERE ct.user_id = u.id AND c.branch_id = uba.branch_id
          )
          AND NOT EXISTS (
              SELECT 1 FROM branch_admins_cte ba
              WHERE ba.branch_id = uba.branch_id AND ba.user_id = u.id
          )
        ORDER BY uba.branch_id, u.id, name
    ),
    aggregated_classrooms AS MATERIALIZED (
        SELECT
            bc.branch_id,
            bc.id AS classroom_id,
            bc.name AS classroom_name,
            bc.room_number,
            bc.capacity,
            COALESCE(
                (SELECT jsonb_agg(
                    jsonb_build_object(
                        'UserId', ct.user_id,
                        'Name', ct.name,
                        'Email', ct.email,
                        'RoleName', ct.role_name,
                        'AssignedClassroomName', bc.name
                    ) ORDER BY ct.is_lead DESC, ct.name
                ) FROM classroom_teachers_cte ct WHERE ct.classroom_id = bc.id AND ct.is_lead = true), '[]'::jsonb
            ) AS lead_teachers,
            COALESCE(
                (SELECT jsonb_agg(
                    jsonb_build_object(
                        'UserId', ct.user_id,
                        'Name', ct.name,
                        'Email', ct.email,
                        'RoleName', ct.role_name,
                        'AssignedClassroomName', bc.name
                    ) ORDER BY ct.name
                ) FROM classroom_teachers_cte ct WHERE ct.classroom_id = bc.id AND ct.is_lead = false), '[]'::jsonb
            ) AS teachers,
            (SELECT count(*)::int FROM classroom_children_cte cc WHERE cc.classroom_id = bc.id) AS student_count,
            COALESCE(
                (SELECT jsonb_agg(
                    jsonb_build_object(
                        'ChildId', cc.child_id,
                        'FullName', cc.full_name,
                        'PhotoUrl', cc.photo_url,
                        'ClassroomName', bc.name,
                        'AssignedTeacherName', fct.assigned_teacher_name
                    ) ORDER BY cc.full_name
                ) FROM classroom_children_cte cc WHERE cc.classroom_id = bc.id), '[]'::jsonb
            ) AS students
        FROM branch_classrooms_cte bc
        LEFT JOIN first_classroom_teacher fct ON fct.classroom_id = bc.id
    ),
    aggregated_branches AS (
        SELECT
            ab.id AS branch_id,
            ab.name AS branch_name,
            ab.location,
            COALESCE(
                (SELECT jsonb_agg(
                    jsonb_build_object(
                        'UserId', ba.user_id,
                        'Name', ba.name,
                        'Email', ba.email,
                        'RoleName', 'Campus Branch Director'
                    ) ORDER BY ba.name
                ) FROM branch_admins_cte ba WHERE ba.branch_id = ab.id), '[]'::jsonb
            ) AS branch_admins,
            COALESCE(
                (SELECT jsonb_agg(
                    jsonb_build_object(
                        'ClassroomId', ac.classroom_id,
                        'ClassroomName', ac.classroom_name,
                        'RoomNumber', ac.room_number,
                        'Capacity', ac.capacity,
                        'LeadTeachers', ac.lead_teachers,
                        'Teachers', ac.teachers,
                        'StudentCount', ac.student_count,
                        'ChildrenLoaded', true,
                        'Students', ac.students
                    ) ORDER BY ac.classroom_name
                ) FROM aggregated_classrooms ac WHERE ac.branch_id = ab.id), '[]'::jsonb
            ) AS classrooms,
            COALESCE(
                (SELECT jsonb_agg(
                    jsonb_build_object(
                        'UserId', ubs.user_id,
                        'Name', ubs.name,
                        'Email', ubs.email,
                        'RoleName', ubs.role_name,
                        'AssignedClassroomName', 'Unassigned Classroom'
                    ) ORDER BY ubs.name
                ) FROM unassigned_branch_staff_cte ubs WHERE ubs.branch_id = ab.id), '[]'::jsonb
            ) AS unassigned_staff,
            (SELECT COALESCE(sum(ac.student_count), 0)::int FROM aggregated_classrooms ac WHERE ac.branch_id = ab.id) AS total_students,
            (SELECT count(DISTINCT ct.user_id)::int FROM classroom_teachers_cte ct
             JOIN aggregated_classrooms ac ON ct.classroom_id = ac.classroom_id WHERE ac.branch_id = ab.id AND ct.is_lead = true) AS lead_teacher_count,
            (SELECT count(DISTINCT ct.user_id)::int FROM classroom_teachers_cte ct
             JOIN aggregated_classrooms ac ON ct.classroom_id = ac.classroom_id WHERE ac.branch_id = ab.id AND ct.is_lead = false) AS teacher_count
        FROM authorized_branches ab
    ),
    all_staff_ids AS (
        SELECT unnest(v_org_admin_ids) AS staff_id
        UNION
        SELECT user_id AS staff_id FROM branch_admins_cte
        UNION
        SELECT user_id AS staff_id FROM classroom_teachers_cte
        UNION
        SELECT user_id AS staff_id FROM unassigned_branch_staff_cte
    )
    SELECT
        COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'BranchId', br.branch_id,
                    'BranchName', br.branch_name,
                    'Location', br.location,
                    'BranchAdmins', br.branch_admins,
                    'Classrooms', br.classrooms,
                    'UnassignedStaff', br.unassigned_staff,
                    'StudentCount', br.total_students,
                    'LeadTeacherCount', br.lead_teacher_count,
                    'TeacherCount', br.teacher_count
                ) ORDER BY br.branch_name
            )
            FROM aggregated_branches br
        ), '[]'::jsonb),
        COALESCE((SELECT sum(total_students)::int FROM aggregated_branches), 0),
        COALESCE((SELECT count(*)::int FROM all_staff_ids WHERE staff_id IS NOT NULL), 0)
    INTO v_branches, v_total_students, v_total_staff;

    RETURN jsonb_build_object(
        'OrganizationId', v_org.id,
        'OrganizationName', v_org.name,
        'Location', v_org.location,
        'Currency', v_org.currency,
        'TotalBranches', jsonb_array_length(v_branches),
        'TotalStaff', v_total_staff,
        'TotalStudents', v_total_students,
        'OrganizationAdmins', v_org_admins,
        'Branches', v_branches
    );
END;
$$;


--
-- Name: fn_get_organization_latest_invitations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_organization_latest_invitations() RETURNS TABLE(out_organization_id uuid, out_admin_email character varying, out_token character varying, out_status character varying, out_expires_at timestamp with time zone, out_created_at timestamp with time zone, out_accepted_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT ON (i.organization_id)
        i.organization_id,
        i.admin_email,
        i.token,
        i.status::VARCHAR,
        i.expires_at,
        i.created_at,
        i.accepted_at
    FROM organization_invitations i
    ORDER BY i.organization_id, i.created_at DESC;
END;
$$;


--
-- Name: fn_get_organization_quota_usage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_organization_quota_usage(p_org_id uuid) RETURNS TABLE(organization_id uuid, plan_id uuid, plan_code character varying, plan_name character varying, max_branches integer, current_branches integer, max_classrooms integer, current_classrooms integer, max_children integer, current_children integer, includes_ai boolean)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        o.id AS organization_id,
        COALESCE(o.plan_id, '22222222-2222-2222-2222-222222222222'::UUID) AS plan_id,
        COALESCE(o.plan_code, 'PLAN-BLOOM')::VARCHAR AS plan_code,
        COALESCE(o.plan_name, 'Bloom (Growth)')::VARCHAR AS plan_name,
        COALESCE(o.max_branches, 2)::INT AS max_branches,
        (SELECT COUNT(*)::INT FROM branches b WHERE b.organization_id = o.id AND b.is_active = TRUE) AS current_branches,
        COALESCE(o.max_classrooms, 8)::INT AS max_classrooms,
        (SELECT COUNT(*)::INT FROM classrooms c JOIN branches b ON c.branch_id = b.id WHERE b.organization_id = o.id AND c.is_active = TRUE) AS current_classrooms,
        COALESCE(o.max_children, 90)::INT AS max_children,
        (SELECT COUNT(*)::INT FROM children ch JOIN classrooms c ON ch.classroom_id = c.id JOIN branches b ON c.branch_id = b.id WHERE b.organization_id = o.id AND ch.is_active = TRUE) AS current_children,
        COALESCE(o.includes_ai, TRUE)::BOOLEAN AS includes_ai
    FROM organizations o
    WHERE o.id = p_org_id;
$$;


--
-- Name: fn_get_organization_role_names(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_organization_role_names(p_tenant_id uuid, p_organization_id uuid, p_user_id uuid) RETURNS TABLE(role_name character varying)
    LANGUAGE sql STABLE
    AS $$
    SELECT r.name::VARCHAR
    FROM user_organization_roles uor
    JOIN roles r ON r.id = uor.role_id AND r.tenant_id = uor.tenant_id
    JOIN organization_memberships m ON m.user_id = uor.user_id AND m.organization_id = uor.organization_id AND m.tenant_id = uor.tenant_id
    WHERE uor.tenant_id = p_tenant_id 
      AND uor.organization_id = p_organization_id 
      AND uor.user_id = p_user_id
      AND m.status = 'Active';
$$;


--
-- Name: fn_get_organization_role_permissions(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_organization_role_permissions(p_tenant_id uuid, p_organization_id uuid) RETURNS TABLE(role_name character varying, feature_key character varying, is_allowed boolean, updated_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        orp.role_name,
        orp.feature_key,
        orp.is_allowed,
        orp.updated_at
    FROM organization_role_permissions orp
    WHERE orp.tenant_id = p_tenant_id
      AND orp.organization_id = p_organization_id;
$$;


--
-- Name: fn_get_organizations_by_user_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_organizations_by_user_id(p_user_id uuid) RETURNS TABLE(id uuid, tenant_id uuid, name character varying, location character varying, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- If user is globally inactive, return nothing
    IF NOT EXISTS (SELECT 1 FROM users u WHERE u.id = p_user_id AND u.is_active = TRUE) THEN
        RETURN;
    END IF;

    RETURN QUERY
    WITH candidate_orgs AS (
        -- Direct active organization memberships
        SELECT om.organization_id
        FROM organization_memberships om
        WHERE om.user_id = p_user_id AND om.status = 'Active'

        UNION

        -- Roles assigned within an organization
        SELECT uor.organization_id
        FROM user_organization_roles uor
        WHERE uor.user_id = p_user_id AND uor.organization_id IS NOT NULL

        UNION

        -- Active branch assignments linked to organizations
        SELECT b.organization_id
        FROM user_branch_assignments uba
        JOIN branches b ON uba.branch_id = b.id
        WHERE uba.user_id = p_user_id AND uba.revoked_at IS NULL AND b.organization_id IS NOT NULL

        UNION

        -- Active classroom assignments linked to organizations
        SELECT b.organization_id
        FROM classroom_teachers ct
        JOIN classrooms c ON ct.classroom_id = c.id
        JOIN branches b ON c.branch_id = b.id
        WHERE ct.user_id = p_user_id AND b.organization_id IS NOT NULL

        UNION

        -- User primary tenant organization match (ONLY if user has no explicit inactive membership for it)
        SELECT o.id as organization_id
        FROM users u
        JOIN organizations o ON o.tenant_id = u.tenant_id
        WHERE u.id = p_user_id AND o.is_active = TRUE
          AND NOT EXISTS (
              SELECT 1 FROM organization_memberships om_check
              WHERE om_check.user_id = p_user_id AND om_check.organization_id = o.id AND om_check.status = 'Inactive'
          )
    )
    SELECT DISTINCT
        o.id,
        o.tenant_id,
        o.name,
        o.location,
        o.is_active,
        o.created_at,
        o.updated_at
    FROM candidate_orgs c
    JOIN organizations o ON c.organization_id = o.id
    WHERE o.is_active = TRUE
      -- STRICT EXCLUSION: If organization is explicitly marked Inactive in organization_memberships, DO NOT RETURN IT!
      AND NOT EXISTS (
          SELECT 1 FROM organization_memberships om_inact
          WHERE om_inact.user_id = p_user_id
            AND om_inact.organization_id = o.id
            AND om_inact.status = 'Inactive'
      )
    ORDER BY o.name;
END;
$$;


--
-- Name: fn_get_organizations_due_for_automatic_billing(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_organizations_due_for_automatic_billing(p_as_of_date timestamp with time zone) RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, mode character varying, frequency character varying, effective_date timestamp with time zone, next_billing_date timestamp with time zone, auto_charge_enabled boolean, notes text, updated_by character varying, updated_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        id, tenant_id, organization_id, mode, frequency, effective_date,
        next_billing_date, auto_charge_enabled, notes, updated_by, updated_at
    FROM organization_billing_settings
    WHERE mode = 'Automatic'
      AND effective_date <= p_as_of_date
      AND (next_billing_date IS NULL OR next_billing_date <= p_as_of_date);
$$;


--
-- Name: events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    title character varying(200) NOT NULL,
    description text,
    event_type_id uuid,
    event_date date NOT NULL,
    start_time time without time zone,
    end_time time without time zone,
    location character varying(255),
    organizer_id uuid,
    status character varying(50) DEFAULT 'Draft'::character varying NOT NULL,
    is_organization_wide boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    scope character varying(30) DEFAULT 'Classroom'::character varying NOT NULL,
    branch_id uuid,
    photo_urls text[] DEFAULT '{}'::text[]
);


--
-- Name: fn_get_parent_approved_events_for_child(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_parent_approved_events_for_child(p_tenant_id uuid, p_child_id uuid) RETURNS SETOF public.events
    LANGUAGE sql STABLE
    AS $$
    SELECT DISTINCT e.*
    FROM events e
    JOIN children c ON c.id = p_child_id
    LEFT JOIN event_classrooms ec ON e.id = ec.event_id
    WHERE (e.tenant_id = c.tenant_id OR e.tenant_id = p_tenant_id)
      AND e.status IN ('Published', 'InProgress', 'Completed')
      AND (
          e.is_organization_wide = true
          OR ec.classroom_id = c.classroom_id
          OR e.branch_id IN (SELECT cl.branch_id FROM classrooms cl WHERE cl.id = c.classroom_id)
      )
    ORDER BY e.event_date DESC, e.start_time;
$$;


