-- Name: fn_get_platform_admin_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_platform_admin_count() RETURNS integer
    LANGUAGE sql STABLE
    AS $$
    SELECT COUNT(DISTINCT ur.user_id)::integer
    FROM user_roles ur
    JOIN roles r ON ur.role_id = r.id
    WHERE r.name IN ('PlatformAdmin', 'SuperAdmin');
$$;


--
-- Name: fn_get_platform_admin_notifications(uuid, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_platform_admin_notifications(p_user_id uuid, p_unread_only boolean DEFAULT false, p_limit integer DEFAULT 30) RETURNS TABLE(id uuid, business_event_id uuid, title character varying, message text, action_url character varying, is_read boolean, read_at timestamp with time zone, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        n.id,
        n.business_event_id,
        n.title::VARCHAR,
        n.message,
        n.action_url::VARCHAR,
        n.is_read,
        n.read_at,
        n.created_at
    FROM public.platform_admin_notifications n
    WHERE (n.user_id = p_user_id OR n.user_id IS NULL)
      AND (NOT p_unread_only OR NOT n.is_read)
    ORDER BY n.created_at DESC
    LIMIT p_limit;
$$;


--
-- Name: fn_get_platform_all_branches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_platform_all_branches() RETURNS TABLE(id uuid, organization_id uuid, name character varying, location character varying, is_active boolean, created_at timestamp with time zone, organization_name character varying, effective_location text, classrooms_count integer, children_count integer)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        b.id AS id,
        b.organization_id AS organization_id,
        b.name AS name,
        b.location AS location,
        b.is_active AS is_active,
        b.created_at AS created_at,
        o.name AS organization_name,
        COALESCE(b.location, o.location, 'Location unspecified') AS effective_location,
        COALESCE((SELECT COUNT(*) FROM classrooms c WHERE c.branch_id = b.id), 0)::int AS classrooms_count,
        COALESCE((SELECT COUNT(*) FROM children ch JOIN classrooms c ON ch.classroom_id = c.id WHERE c.branch_id = b.id), 0)::int AS children_count
    FROM branches b
    JOIN organizations o ON b.organization_id = o.id
    ORDER BY o.name, b.name;
$$;


--
-- Name: fn_get_platform_business_events(integer, integer, character varying, character varying, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_platform_business_events(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_category character varying DEFAULT NULL::character varying, p_event_type character varying DEFAULT NULL::character varying, p_organization_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, event_type character varying, tenant_id uuid, organization_id uuid, organization_name character varying, branch_id uuid, branch_name character varying, initiated_by_user_id uuid, initiator_name character varying, transaction_reference character varying, transaction_category character varying, title character varying, description text, amount numeric, currency character varying, status character varying, event_payload jsonb, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
    SELECT 
        e.id,
        e.event_type::VARCHAR,
        e.tenant_id,
        e.organization_id,
        COALESCE(org.name, 'Unknown Organization')::VARCHAR AS organization_name,
        e.branch_id,
        COALESCE(b.name, 'All Branches')::VARCHAR AS branch_name,
        e.initiated_by_user_id,
        COALESCE(u.display_name, u.email, 'System')::VARCHAR AS initiator_name,
        e.transaction_reference::VARCHAR,
        e.transaction_category::VARCHAR,
        e.title::VARCHAR,
        e.description,
        e.amount,
        e.currency::VARCHAR,
        e.status::VARCHAR,
        e.event_payload,
        e.created_at
    FROM public.platform_business_events e
    JOIN public.organizations org ON e.organization_id = org.id
    LEFT JOIN public.branches b ON e.branch_id = b.id
    LEFT JOIN public.users u ON e.initiated_by_user_id = u.id
    WHERE (p_category IS NULL OR p_category = '' OR p_category = 'All' OR e.transaction_category = p_category)
      AND (p_event_type IS NULL OR p_event_type = '' OR p_event_type = 'All' OR e.event_type = p_event_type)
      AND (p_organization_id IS NULL OR e.organization_id = p_organization_id)
    ORDER BY e.created_at DESC
    LIMIT p_limit OFFSET p_offset;
$$;


