$$;


--
-- Name: fn_has_active_membership(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_has_active_membership(p_tenant_id uuid, p_organization_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN EXISTS(
        SELECT 1 FROM organization_memberships m
        JOIN users u ON u.id = m.user_id
        WHERE m.tenant_id = p_tenant_id AND m.organization_id = p_organization_id AND m.user_id = p_user_id
          AND m.status = 'Active' AND u.is_active = true
    );
END;
$$;


--
-- Name: fn_has_active_onboarded_child(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_has_active_onboarded_child(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM family_relationships fr
        JOIN children c ON c.id = fr.child_id
        WHERE fr.user_id = p_user_id
          AND fr.status = 'Verified'
          AND fr.revoked_at IS NULL
          AND c.is_active = TRUE
          AND c.enrollment_status = 'Enrolled'
    )
    OR EXISTS (
        SELECT 1
        FROM child_guardians cg
        JOIN persons p ON p.id = cg.person_id
        JOIN children c ON c.id = cg.child_id
        WHERE p.user_id = p_user_id
          AND p.has_portal_access = TRUE
          AND c.is_active = TRUE
          AND c.enrollment_status = 'Enrolled'
    );
$$;


--
-- Name: fn_has_journey_entry_for_participation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_has_journey_entry_for_participation(p_tenant_id uuid, p_participation_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 
        FROM child_journey_entries 
        WHERE tenant_id = p_tenant_id 
          AND experience_participation_id = p_participation_id
    );
END;
$$;


--
-- Name: fn_has_parent_child_access(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_has_parent_child_access(p_tenant_id uuid, p_user_id uuid, p_child_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM family_relationships fr
        JOIN children c ON fr.child_id = c.id
        WHERE fr.user_id = p_user_id
          AND fr.child_id = p_child_id
          AND fr.status = 'Verified' 
          AND fr.revoked_at IS NULL
          AND c.is_active = true
    );
$$;


--
-- Name: fn_has_verified_guardian_relationship(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_has_verified_guardian_relationship(p_tenant_id uuid, p_user_id uuid, p_child_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN EXISTS(
        SELECT 1 FROM family_relationships fr
        JOIN children c ON c.id = fr.child_id AND c.tenant_id = fr.tenant_id
        JOIN users u ON u.id = fr.user_id AND u.tenant_id = fr.tenant_id
        WHERE fr.tenant_id = p_tenant_id AND fr.user_id = p_user_id AND fr.child_id = p_child_id
          AND fr.status = 'Verified' AND fr.revoked_at IS NULL
          AND c.is_active = true AND u.is_active = true
    );
END;
$$;


--
-- Name: fn_insert_child_fee_adjustment(uuid, uuid, uuid, uuid, uuid, uuid, uuid, character varying, numeric, numeric, numeric, text, date, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_insert_child_fee_adjustment(p_id uuid, p_tenant_id uuid, p_organization_id uuid, p_branch_id uuid, p_child_id uuid, p_contract_id uuid, p_invoice_id uuid, p_adjustment_type character varying, p_previous_amount numeric, p_new_amount numeric, p_adjustment_delta numeric, p_reason text, p_effective_date date, p_adjusted_by_user_id uuid, p_adjusted_by_email character varying) RETURNS SETOF public.child_fee_adjustments
    LANGUAGE sql
    AS $$
    INSERT INTO child_fee_adjustments (
        id, tenant_id, organization_id, branch_id, child_id, contract_id, invoice_id,
        adjustment_type, previous_amount, new_amount, adjustment_delta, reason,
        effective_date, adjusted_by_user_id, adjusted_by_email, created_at
    ) VALUES (
        p_id, p_tenant_id, p_organization_id, p_branch_id, p_child_id, p_contract_id, p_invoice_id,
        p_adjustment_type, p_previous_amount, p_new_amount, p_adjustment_delta, p_reason,
        p_effective_date, p_adjusted_by_user_id, p_adjusted_by_email, NOW()
    )
    RETURNING *;
$$;


--
-- Name: fn_is_privacy_and_trust_approved(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_is_privacy_and_trust_approved(p_tenant_id uuid, p_child_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM child_consents
        WHERE child_id = p_child_id
          AND consent_type = 'PrivacyAndTrust' AND granted = TRUE
          AND (tenant_id = p_tenant_id OR p_tenant_id IS NULL 
               OR p_tenant_id = '10000000-0000-0000-0000-000000000001' 
               OR tenant_id = (SELECT tenant_id FROM children WHERE id = p_child_id))
    );
$$;


--
-- Name: fn_is_teacher_assigned_to_classroom(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_is_teacher_assigned_to_classroom(p_tenant_id uuid, p_classroom_id uuid, p_teacher_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1
        FROM classroom_teachers ct
        WHERE ct.tenant_id = p_tenant_id 
          AND ct.classroom_id = p_classroom_id 
          AND (ct.user_id = p_teacher_id OR (p_user_id IS NOT NULL AND ct.user_id = p_user_id))
    );
END;
$$;


--
-- Name: fn_publish_tuition_invoice(uuid, character varying, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_publish_tuition_invoice(p_invoice_id uuid, p_published_by character varying, p_payment_instructions text, p_payment_instructions_snapshot text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE invoices
    SET status = 'Issued',
        published_at = NOW(),
        published_by = p_published_by,
        payment_instructions = COALESCE(p_payment_instructions, payment_instructions),
        payment_instructions_snapshot = COALESCE(
            CASE WHEN p_payment_instructions_snapshot IS NOT NULL AND LENGTH(TRIM(p_payment_instructions_snapshot)) > 0 THEN p_payment_instructions_snapshot::jsonb ELSE NULL END,
            payment_instructions_snapshot
        ),
        updated_at = NOW()
    WHERE id = p_invoice_id
      AND status = 'Draft';
    RETURN FOUND;
END;
$$;


--
-- Name: fn_reassign_event_organizer(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reassign_event_organizer(p_tenant_id uuid, p_event_id uuid, p_new_user_id uuid, p_reassigned_by uuid, p_branch_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    e record;
    v_classroom uuid;
    v_ok boolean;
    v_reason text;
    v_old_teacher uuid;
    v_new_teacher uuid;
BEGIN
    SELECT * INTO e FROM events WHERE id = p_event_id AND tenant_id = p_tenant_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Event not found' USING ERRCODE = 'EE404';
    END IF;

    SELECT ec.classroom_id INTO v_classroom
    FROM event_classrooms ec JOIN classrooms c ON c.id = ec.classroom_id
    WHERE ec.event_id = p_event_id AND c.branch_id = p_branch_id LIMIT 1;
    IF v_classroom IS NULL THEN
        RAISE EXCEPTION 'Event does not belong to this branch' USING ERRCODE = 'EE403';
    END IF;

    -- Serialize per teacher so two admins cannot double-book the same person.
    PERFORM pg_advisory_xact_lock(hashtextextended('teacher-slot:' || p_new_user_id::text, 0));

    SELECT a.is_available, a.reason INTO v_ok, v_reason
    FROM public.fn_get_available_cover_teachers(p_tenant_id, p_branch_id, v_classroom, e.event_date, e.start_time, e.end_time, p_event_id) a
    WHERE a.user_id = p_new_user_id;

    IF v_ok IS NULL THEN
        RAISE EXCEPTION 'Selected teacher is not assigned to this branch' USING ERRCODE = 'EE409';
    ELSIF NOT v_ok THEN
        RAISE EXCEPTION 'Selected teacher is not available: %', v_reason USING ERRCODE = 'EE409';
    END IF;

    UPDATE events SET organizer_id = p_new_user_id, updated_at = now() WHERE id = p_event_id;
    UPDATE event_tasks SET owner_id = p_new_user_id, updated_at = now()
     WHERE event_id = p_event_id AND is_completed = false AND (owner_id = e.organizer_id OR owner_id IS NULL);

    SELECT id INTO v_old_teacher FROM teachers WHERE user_id = e.organizer_id AND tenant_id = p_tenant_id LIMIT 1;
    SELECT id INTO v_new_teacher FROM teachers WHERE user_id = p_new_user_id AND tenant_id = p_tenant_id LIMIT 1;

    IF v_old_teacher IS NOT NULL THEN
        UPDATE staff_leaves sl
           SET substitute_teacher_id = COALESCE(sl.substitute_teacher_id, v_new_teacher),
               reviewed_by_user_id = p_reassigned_by,
               coverage_status = CASE WHEN EXISTS (
                    SELECT 1 FROM events x JOIN event_classrooms xc ON xc.event_id = x.id
                    WHERE x.tenant_id = p_tenant_id AND x.organizer_id = e.organizer_id
                      AND x.status NOT IN ('Cancelled','Completed')
                      AND x.event_date BETWEEN sl.start_date AND sl.end_date)
                  THEN 'Uncovered' ELSE 'Covered' END
         WHERE sl.teacher_id = v_old_teacher AND sl.tenant_id = p_tenant_id AND sl.status = 'Approved'
           AND e.event_date BETWEEN sl.start_date AND sl.end_date;
    END IF;

    INSERT INTO audit_log (tenant_id, user_id, action, entity_type, entity_id, details)
    VALUES (p_tenant_id, p_reassigned_by, 'EventOrganizerReassigned', 'Event', p_event_id,
            jsonb_build_object('from_user_id', e.organizer_id, 'to_user_id', p_new_user_id,
                               'event_date', e.event_date, 'classroom_id', v_classroom));
END;
$$;


--
-- Name: fn_record_org_razorpay_payment(uuid, uuid, uuid, uuid, uuid, uuid, character varying, numeric, character varying, character varying, character varying, character varying, uuid, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_record_org_razorpay_payment(p_id uuid, p_tenant_id uuid, p_organization_id uuid, p_branch_id uuid, p_child_id uuid, p_invoice_id uuid, p_invoice_number character varying, p_amount numeric, p_currency character varying, p_provider_order_id character varying, p_provider_payment_id character varying, p_provider_signature character varying, p_recorded_by_user_id uuid, p_recorded_by_email character varying, p_notes text) RETURNS TABLE(success boolean, message text, payment_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_existing UUID;
    v_invoice invoices%ROWTYPE;
    v_effective_payable NUMERIC(14,2);
    v_remaining NUMERIC(14,2);
BEGIN
    SELECT id INTO v_existing
    FROM payments
    WHERE provider_payment_id = p_provider_payment_id
      AND is_reversed = FALSE
    LIMIT 1;

    IF v_existing IS NOT NULL THEN
        RETURN QUERY SELECT TRUE, 'Payment already recorded.', v_existing;
        RETURN;
    END IF;

    SELECT * INTO v_invoice
    FROM invoices
    WHERE id = p_invoice_id
      AND organization_id = p_organization_id
      AND billing_domain = 'OrgToParent'
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Parent invoice not found for this organization.', NULL::UUID;
        RETURN;
    END IF;

    v_effective_payable := GREATEST(0, v_invoice.total_amount - COALESCE(v_invoice.adjustment_amount, 0));
    v_remaining := GREATEST(0, v_effective_payable - v_invoice.amount_paid);

    IF p_amount <= 0 OR p_amount > v_remaining THEN
        RETURN QUERY SELECT FALSE, format('Payment amount (%s) exceeds remaining balance (%s).', p_amount, v_remaining), NULL::UUID;
        RETURN;
    END IF;

    INSERT INTO payments (
        id, tenant_id, organization_id, branch_id, child_id, invoice_id, invoice_number,
        payment_reference, amount, currency, method, is_verified, verified_by, verified_at,
        status, transaction_id, notes, provider_order_id, provider_payment_id, provider_signature,
        submission_source, recorded_by_user_id, recorded_by_email, billing_domain, payment_date, created_at
    ) VALUES (
        p_id, p_tenant_id, p_organization_id, p_branch_id, p_child_id, p_invoice_id, p_invoice_number,
        p_provider_payment_id, p_amount, p_currency, 'Razorpay', TRUE, 'Organization Razorpay Gateway', NOW(),
        'Completed', p_provider_payment_id, p_notes, p_provider_order_id, p_provider_payment_id, p_provider_signature,
        'ParentPortalRazorpay', p_recorded_by_user_id, p_recorded_by_email, 'OrgToParent', NOW(), NOW()
    );

    CALL public.sp_recalculate_invoice_balance(p_invoice_id);

    RETURN QUERY SELECT TRUE, 'Razorpay payment verified and applied.', p_id;
END;
$$;


--
-- Name: fn_record_teacher_attendance(uuid, uuid, uuid, uuid, timestamp with time zone, character varying, interval, interval, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_record_teacher_attendance(p_id uuid, p_tenant_id uuid, p_branch_id uuid, p_teacher_id uuid, p_attendance_date timestamp with time zone, p_status character varying, p_clock_in_time interval, p_clock_out_time interval, p_notes text, p_recorded_by_user_id uuid) RETURNS TABLE(id uuid, tenant_id uuid, branch_id uuid, teacher_id uuid, attendance_date date, status character varying, clock_in_time time without time zone, clock_out_time time without time zone, notes text, recorded_by_user_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actual_teacher_id UUID;
    v_attendance_id UUID;
    v_user RECORD;
BEGIN
    SELECT t.id INTO v_actual_teacher_id FROM teachers t WHERE t.id = p_teacher_id OR t.user_id = p_teacher_id LIMIT 1;
    
    IF v_actual_teacher_id IS NULL THEN
        SELECT u.id, u.tenant_id, u.first_name, u.last_name, u.display_name INTO v_user FROM users u WHERE u.id = p_teacher_id;
        IF v_user.id IS NOT NULL THEN
            v_actual_teacher_id := gen_random_uuid();
            INSERT INTO teachers (id, tenant_id, user_id, first_name, last_name, display_name, status, created_at, updated_at)
            VALUES (
                v_actual_teacher_id,
                p_tenant_id,
                v_user.id,
                COALESCE(v_user.first_name, 'Teacher'),
                COALESCE(v_user.last_name, ''),
                COALESCE(v_user.display_name, 'Teacher'),
                'Active',
                CURRENT_TIMESTAMP,
                CURRENT_TIMESTAMP
            );
        END IF;
    END IF;

    IF v_actual_teacher_id IS NULL THEN
        v_actual_teacher_id := p_teacher_id;
    END IF;

    SELECT ta.id INTO v_attendance_id
    FROM teacher_attendance ta
    WHERE ta.tenant_id = p_tenant_id
      AND ta.teacher_id = v_actual_teacher_id
      AND ta.attendance_date = p_attendance_date::DATE
    LIMIT 1;

    IF v_attendance_id IS NOT NULL THEN
        UPDATE teacher_attendance
        SET branch_id = p_branch_id,
            status = p_status,
            clock_in_time = COALESCE(p_clock_in_time::time, clock_in_time),
            clock_out_time = COALESCE(p_clock_out_time::time, clock_out_time),
            notes = COALESCE(p_notes, notes),
            recorded_by_user_id = p_recorded_by_user_id,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = v_attendance_id;
    ELSE
        v_attendance_id := COALESCE(p_id, gen_random_uuid());
        INSERT INTO teacher_attendance (
            id, tenant_id, branch_id, teacher_id, attendance_date, status,
            clock_in_time, clock_out_time, notes, recorded_by_user_id,
            created_at, updated_at
        )
        VALUES (
            v_attendance_id, p_tenant_id, p_branch_id, v_actual_teacher_id, p_attendance_date::DATE, p_status,
            p_clock_in_time::time, p_clock_out_time::time, p_notes, p_recorded_by_user_id,
            CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
        );
    END IF;

    RETURN QUERY
    SELECT ta.id, ta.tenant_id, ta.branch_id, ta.teacher_id, ta.attendance_date, ta.status,
           ta.clock_in_time, ta.clock_out_time, ta.notes, ta.recorded_by_user_id,
           ta.created_at, ta.updated_at
    FROM teacher_attendance ta
    WHERE ta.id = v_attendance_id;
END;
$$;


--
-- Name: fn_reject_gifting_payment(uuid, uuid, character varying, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reject_gifting_payment(p_payment_id uuid, p_actor_user_id uuid, p_actor_name character varying, p_actor_role character varying, p_rejection_reason text) RETURNS TABLE(success boolean, message text, order_id uuid, payment_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_payment payments%ROWTYPE;
    v_order classroom_gifting_orders%ROWTYPE;
BEGIN
    SELECT * INTO v_payment
    FROM payments
    WHERE id = p_payment_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Payment record not found.'::TEXT, NULL::UUID, p_payment_id;
        RETURN;
    END IF;

    SELECT * INTO v_order
    FROM classroom_gifting_orders
    WHERE id = v_payment.gifting_order_id
    FOR UPDATE;

    UPDATE payments
    SET status = 'Rejected',
        rejected_by = p_actor_name,
        rejected_at = NOW(),
        rejection_reason = p_rejection_reason
    WHERE id = p_payment_id;

    UPDATE classroom_gifting_orders
    SET payment_status = 'PaymentRejected',
        updated_at = NOW()
    WHERE id = v_order.id;

    INSERT INTO classroom_gifting_audit_events (
        order_id, tenant_id, organization_id, branch_id, classroom_id,
        event_type, previous_status, new_status, actor_user_id, actor_name,
        actor_role, description, notes
    ) VALUES (
        v_order.id, v_order.tenant_id, v_order.organization_id, v_order.branch_id, v_order.classroom_id,
        'PaymentRejected', 'PaymentVerificationPending', 'PaymentRejected',
        p_actor_user_id, p_actor_name, p_actor_role,
        format('Payment submission (%s %s) rejected by %s. Reason: %s', v_payment.currency, v_payment.amount, p_actor_name, p_rejection_reason),
        p_rejection_reason
    );

    RETURN QUERY SELECT TRUE, 'Payment submission rejected.'::TEXT, v_order.id, p_payment_id;
END;
$$;


--
-- Name: fn_reject_submitted_payment(uuid, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_reject_submitted_payment(p_payment_id uuid, p_rejected_by character varying, p_reason text) RETURNS TABLE(success boolean, message text, invoice_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_payment payments%ROWTYPE;
BEGIN
    SELECT * INTO v_payment
    FROM payments
    WHERE id = p_payment_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Payment submission not found.', NULL::UUID;
        RETURN;
    END IF;

    IF v_payment.is_verified OR v_payment.status = 'Completed' THEN
        RETURN QUERY SELECT FALSE, 'Verified payments cannot be rejected; use reversal/adjustment instead.', v_payment.invoice_id;
        RETURN;
    END IF;

    IF v_payment.status <> 'PendingVerification' THEN
        RETURN QUERY SELECT FALSE, 'Payment is not awaiting verification.', v_payment.invoice_id;
        RETURN;
    END IF;

    UPDATE payments
    SET status = 'Rejected',
        is_verified = FALSE,
        rejection_reason = COALESCE(NULLIF(TRIM(p_reason), ''), 'Rejected by daycare staff'),
        rejected_by = p_rejected_by,
        rejected_at = NOW()
    WHERE id = p_payment_id;

    IF v_payment.invoice_id IS NOT NULL THEN
        CALL public.sp_recalculate_invoice_balance(v_payment.invoice_id);
    END IF;

    RETURN QUERY SELECT TRUE, 'Payment submission rejected.', v_payment.invoice_id;
END;
$$;


--
-- Name: fn_resolve_child_tariff(uuid, uuid, uuid, uuid, uuid, character varying, character varying, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_resolve_child_tariff(p_tenant_id uuid, p_organization_id uuid, p_branch_id uuid DEFAULT NULL::uuid, p_classroom_id uuid DEFAULT NULL::uuid, p_child_id uuid DEFAULT NULL::uuid, p_location_tier character varying DEFAULT NULL::character varying, p_billing_frequency character varying DEFAULT NULL::character varying, p_as_of_date date DEFAULT CURRENT_DATE) RETURNS TABLE(rule_id uuid, fee_plan_id uuid, plan_name character varying, fee_category character varying, billing_frequency character varying, scope_type character varying, precedence_rank integer, amount numeric, currency character varying, allow_partial_payment boolean, minimum_partial_payment numeric, allow_parent_cash_declaration boolean, location_tier character varying, notes text)
    LANGUAGE sql STABLE
    AS $$
    WITH resolved AS (
        SELECT
            r.id AS rule_id,
            r.fee_plan_id,
            p.name AS plan_name,
            p.fee_category,
            p.billing_frequency,
            r.scope_type,
            CASE r.scope_type
                WHEN 'Child' THEN 1
                WHEN 'Classroom' THEN 2
                WHEN 'Branch' THEN 3
                WHEN 'LocationTier' THEN 4
                WHEN 'OrgDefault' THEN 5
                ELSE 99
            END AS precedence_rank,
            r.amount,
            r.currency,
            p.allow_partial_payment,
            p.minimum_partial_payment,
            p.allow_parent_cash_declaration,
            r.location_tier,
            r.notes,
            r.effective_date
        FROM org_tariff_rules r
        INNER JOIN org_fee_plans p ON p.id = r.fee_plan_id
        WHERE r.tenant_id = p_tenant_id
          AND r.organization_id = p_organization_id
          AND r.is_active = TRUE
          AND p.is_active = TRUE
          AND r.effective_date <= p_as_of_date
          AND (r.expiry_date IS NULL OR r.expiry_date >= p_as_of_date)
          AND (p_billing_frequency IS NULL OR LOWER(p.billing_frequency) = LOWER(p_billing_frequency))
          AND (
              (r.scope_type = 'Child' AND p_child_id IS NOT NULL AND r.child_id = p_child_id)
              OR (r.scope_type = 'Classroom' AND p_classroom_id IS NOT NULL AND r.classroom_id = p_classroom_id)
              OR (r.scope_type = 'Branch' AND p_branch_id IS NOT NULL AND r.branch_id = p_branch_id)
              OR (r.scope_type = 'LocationTier' AND p_location_tier IS NOT NULL AND LOWER(r.location_tier) = LOWER(p_location_tier))
              OR (r.scope_type = 'OrgDefault')
          )
    )
    SELECT
        rule_id, fee_plan_id, plan_name, fee_category, billing_frequency,
        scope_type, precedence_rank, amount, currency,
        allow_partial_payment, minimum_partial_payment, allow_parent_cash_declaration,
        location_tier, notes
    FROM resolved
    ORDER BY precedence_rank ASC, effective_date DESC
    LIMIT 1;
$$;


--
-- Name: fn_resolve_pricing_region(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_resolve_pricing_region(p_location text) RETURNS TABLE(id uuid, code character varying, name character varying, description text, currency character varying, matched_cities jsonb, matched_states jsonb, is_default boolean, is_active boolean)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_clean_loc TEXT;
    v_matched_id UUID;
BEGIN
    v_clean_loc := LOWER(COALESCE(TRIM(p_location), ''));

    IF v_clean_loc != '' THEN
        -- Match city or state in JSONB arrays (case-insensitive substring check)
        SELECT pr.id INTO v_matched_id
        FROM pricing_regions pr
        WHERE pr.is_active = TRUE
          AND (
            EXISTS (
                SELECT 1 
                FROM jsonb_array_elements_text(pr.matched_cities) c 
                WHERE v_clean_loc LIKE '%' || LOWER(TRIM(c)) || '%'
            )
            OR
            EXISTS (
                SELECT 1 
                FROM jsonb_array_elements_text(pr.matched_states) s 
                WHERE v_clean_loc LIKE '%' || LOWER(TRIM(s)) || '%'
            )
          )
        ORDER BY pr.display_order ASC, pr.created_at ASC
        LIMIT 1;
    END IF;

    -- If no region matched, fallback to default region
    IF v_matched_id IS NULL THEN
        SELECT pr.id INTO v_matched_id
        FROM pricing_regions pr
        WHERE pr.is_active = TRUE AND pr.is_default = TRUE
        LIMIT 1;
    END IF;

    -- If still no default found, take any active region
    IF v_matched_id IS NULL THEN
        SELECT pr.id INTO v_matched_id
        FROM pricing_regions pr
        WHERE pr.is_active = TRUE
        ORDER BY pr.display_order ASC
        LIMIT 1;
    END IF;

    RETURN QUERY
    SELECT pr.id, pr.code, pr.name, pr.description, pr.currency, pr.matched_cities, pr.matched_states, pr.is_default, pr.is_active
    FROM pricing_regions pr
    WHERE pr.id = v_matched_id;
END;
$$;


--
-- Name: fn_resolve_teacher_id(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_resolve_teacher_id(p_tenant_id uuid, p_teacher_or_user_id uuid, p_classroom_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_found_id UUID;
    v_new_teacher_id UUID;
BEGIN
    -- 1. Direct teacher ID
    SELECT t.id INTO v_found_id
    FROM teachers t
    WHERE t.id = p_teacher_or_user_id AND t.tenant_id = p_tenant_id
    LIMIT 1;

    IF v_found_id IS NOT NULL THEN
        RETURN v_found_id;
    END IF;

    -- 2. User ID linked to teacher
    SELECT t.id INTO v_found_id
    FROM teachers t
    WHERE t.user_id = p_teacher_or_user_id AND t.tenant_id = p_tenant_id
    LIMIT 1;

    IF v_found_id IS NOT NULL THEN
        RETURN v_found_id;
    END IF;

    -- 3. Classroom teacher
    IF p_classroom_id IS NOT NULL THEN
        SELECT t.id INTO v_found_id
        FROM classroom_teachers ct
        JOIN teachers t ON ct.user_id = t.user_id AND ct.tenant_id = t.tenant_id
        WHERE ct.classroom_id = p_classroom_id AND ct.tenant_id = p_tenant_id
        ORDER BY ct.is_primary DESC
        LIMIT 1;

        IF v_found_id IS NOT NULL THEN
            RETURN v_found_id;
        END IF;
    END IF;

    -- 4. Any active teacher
    SELECT t.id INTO v_found_id
    FROM teachers t
    WHERE t.tenant_id = p_tenant_id AND t.status != 'Inactive'
    LIMIT 1;

    IF v_found_id IS NOT NULL THEN
        RETURN v_found_id;
    END IF;

    -- 5. Auto-create if user exists
    v_new_teacher_id := gen_random_uuid();
    INSERT INTO teachers (
        id, tenant_id, user_id, first_name, last_name, display_name, status, created_at, updated_at
    )
    SELECT v_new_teacher_id, p_tenant_id, u.id, COALESCE(u.first_name, 'Teacher'), COALESCE(u.last_name, 'Staff'), COALESCE(u.display_name, 'Lead Educator'), 'Active', NOW(), NOW()
    FROM users u
    WHERE u.id = p_teacher_or_user_id AND u.tenant_id = p_tenant_id
    ON CONFLICT (id) DO NOTHING;

    IF FOUND THEN
        RETURN v_new_teacher_id;
    END IF;

    RETURN p_teacher_or_user_id;
END;
$$;


--
-- Name: fn_set_org_fee_plan_active(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_set_org_fee_plan_active(p_tenant_id uuid, p_organization_id uuid, p_plan_id uuid, p_is_active boolean) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE org_fee_plans
    SET is_active = p_is_active, updated_at = NOW()
    WHERE id = p_plan_id AND tenant_id = p_tenant_id AND organization_id = p_organization_id;
    RETURN FOUND;
END;
$$;


--
-- Name: fn_set_org_tariff_rule_active(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_set_org_tariff_rule_active(p_tenant_id uuid, p_organization_id uuid, p_rule_id uuid, p_is_active boolean) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE org_tariff_rules
    SET is_active = p_is_active, updated_at = NOW()
    WHERE id = p_rule_id AND tenant_id = p_tenant_id AND organization_id = p_organization_id;
    RETURN FOUND;
END;
$$;


