--
-- Name: fn_validate_and_set_organization(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_validate_and_set_organization(p_user_id uuid, p_organization_id uuid DEFAULT NULL::uuid) RETURNS TABLE(is_valid boolean, tenant_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
    v_is_user_active BOOLEAN;
BEGIN
    -- Check user active status
    SELECT is_active INTO v_is_user_active FROM users WHERE id = p_user_id;
    IF v_is_user_active IS NOT TRUE THEN
        RETURN QUERY SELECT FALSE, NULL::UUID;
        RETURN;
    END IF;

    IF p_organization_id IS NOT NULL THEN
        -- Check if user is explicitly deactivated from this organization
        IF EXISTS (
            SELECT 1 FROM organization_memberships om
            WHERE om.user_id = p_user_id AND om.organization_id = p_organization_id AND om.status = 'Inactive'
        ) THEN
            RETURN QUERY SELECT FALSE, NULL::UUID;
            RETURN;
        END IF;

        -- Check if organization is accessible via active memberships, roles, branch assignments or classroom assignments
        SELECT o.tenant_id INTO v_tenant_id
        FROM organizations o
        WHERE o.id = p_organization_id
          AND o.is_active = TRUE
          AND (
              EXISTS (
                  SELECT 1 FROM organization_memberships om
                  WHERE om.user_id = p_user_id AND om.organization_id = p_organization_id AND om.status = 'Active'
              )
              OR EXISTS (
                  SELECT 1 FROM user_organization_roles uor
                  WHERE uor.user_id = p_user_id AND uor.organization_id = p_organization_id
              )
              OR EXISTS (
                  SELECT 1 FROM user_branch_assignments uba
                  JOIN branches b ON uba.branch_id = b.id
                  WHERE uba.user_id = p_user_id AND b.organization_id = p_organization_id AND uba.revoked_at IS NULL
              )
              OR EXISTS (
                  SELECT 1 FROM classroom_teachers ct
                  JOIN classrooms c ON ct.classroom_id = c.id
                  JOIN branches b ON c.branch_id = b.id
                  WHERE ct.user_id = p_user_id AND b.organization_id = p_organization_id
              )
              OR EXISTS (
                  SELECT 1 FROM users u
                  WHERE u.id = p_user_id AND u.tenant_id = o.tenant_id
              )
          )
        LIMIT 1;

        IF v_tenant_id IS NOT NULL THEN
            -- Ensure an active organization_membership record exists ONLY IF not already Inactive
            INSERT INTO organization_memberships (user_id, organization_id, tenant_id, status, created_at, updated_at)
            VALUES (p_user_id, p_organization_id, v_tenant_id, 'Active', NOW(), NOW())
            ON CONFLICT (user_id, organization_id) DO NOTHING;

            RETURN QUERY SELECT TRUE, v_tenant_id;
        ELSE
            RETURN QUERY SELECT FALSE, NULL::UUID;
        END IF;
    ELSE
        -- Parent context fallback without organization
        IF EXISTS (SELECT 1 FROM family_relationships WHERE user_id = p_user_id AND status = 'Verified' AND revoked_at IS NULL) THEN
            SELECT u.tenant_id INTO v_tenant_id FROM users u WHERE u.id = p_user_id;
            RETURN QUERY SELECT TRUE, v_tenant_id;
        ELSE
            RETURN QUERY SELECT FALSE, NULL::UUID;
        END IF;
    END IF;
END;
$$;


--
-- Name: fn_validate_organization_invitation(character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_validate_organization_invitation(p_token character varying) RETURNS TABLE(out_valid boolean, out_invitation_id uuid, out_organization_id uuid, out_tenant_id uuid, out_organization_name character varying, out_admin_email character varying, out_expires_at timestamp with time zone, out_status character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    r_inv RECORD;
    v_org_name VARCHAR;
BEGIN
    SELECT * INTO r_inv
    FROM organization_invitations
    WHERE token = p_token
    LIMIT 1;

    IF r_inv IS NULL THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, NULL::UUID, NULL::UUID, ''::VARCHAR, ''::VARCHAR, NULL::TIMESTAMPTZ, 'NotFound'::VARCHAR;
        RETURN;
    END IF;

    IF r_inv.status <> 'Pending' THEN
        RETURN QUERY SELECT FALSE, r_inv.id, r_inv.organization_id, r_inv.tenant_id, ''::VARCHAR, r_inv.admin_email, r_inv.expires_at, r_inv.status::VARCHAR;
        RETURN;
    END IF;

    IF r_inv.expires_at < now() THEN
        UPDATE organization_invitations SET status = 'Expired', updated_at = now() WHERE id = r_inv.id;
        RETURN QUERY SELECT FALSE, r_inv.id, r_inv.organization_id, r_inv.tenant_id, ''::VARCHAR, r_inv.admin_email, r_inv.expires_at, 'Expired'::VARCHAR;
        RETURN;
    END IF;

    SELECT name INTO v_org_name FROM organizations WHERE id = r_inv.organization_id;

    RETURN QUERY SELECT TRUE, r_inv.id, r_inv.organization_id, r_inv.tenant_id, COALESCE(v_org_name, 'Daycare Organization')::VARCHAR, r_inv.admin_email, r_inv.expires_at, 'Pending'::VARCHAR;
END;
$$;


--
-- Name: fn_verify_gifting_payment(uuid, uuid, character varying, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_verify_gifting_payment(p_payment_id uuid, p_verifier_user_id uuid, p_verifier_name character varying, p_verifier_role character varying, p_remarks text DEFAULT NULL::text) RETURNS TABLE(success boolean, message text, order_id uuid, payment_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_payment payments%ROWTYPE;
    v_order classroom_gifting_orders%ROWTYPE;
    v_total_paid NUMERIC;
BEGIN
    SELECT * INTO v_payment
    FROM payments
    WHERE id = p_payment_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Payment submission not found.'::TEXT, NULL::UUID, p_payment_id;
        RETURN;
    END IF;

    IF v_payment.gifting_order_id IS NULL THEN
        RETURN QUERY SELECT FALSE, 'This payment is not linked to a gifting order.'::TEXT, NULL::UUID, p_payment_id;
        RETURN;
    END IF;

    SELECT * INTO v_order
    FROM classroom_gifting_orders
    WHERE id = v_payment.gifting_order_id
    FOR UPDATE;

    IF v_payment.is_verified OR v_payment.status = 'Completed' THEN
        RETURN QUERY SELECT FALSE, 'This payment has already been verified.'::TEXT, v_order.id, p_payment_id;
        RETURN;
    END IF;

    -- Update payment
    UPDATE payments
    SET is_verified = TRUE,
        verified_by = p_verifier_name,
        verified_at = NOW(),
        status = 'Completed',
        notes = CASE 
            WHEN p_remarks IS NOT NULL AND LENGTH(TRIM(p_remarks)) > 0
                THEN COALESCE(notes || E'\nVerification: ', 'Verification: ') || p_remarks
            ELSE notes
        END
    WHERE id = p_payment_id;

    -- Calculate total verified paid for this order
    SELECT COALESCE(SUM(amount), 0) INTO v_total_paid
    FROM payments
    WHERE gifting_order_id = v_order.id
      AND is_verified = TRUE
      AND status = 'Completed'
      AND is_reversed = FALSE;

    -- Update order payment status
    UPDATE classroom_gifting_orders
    SET payment_status = CASE
            WHEN v_total_paid >= total_amount THEN 'Paid'
            ELSE 'PartiallyPaid'
        END,
        updated_at = NOW()
    WHERE id = v_order.id;

    -- Record audit event
    INSERT INTO classroom_gifting_audit_events (
        order_id, tenant_id, organization_id, branch_id, classroom_id,
        event_type, previous_status, new_status, actor_user_id, actor_name,
        actor_role, description, notes
    ) VALUES (
        v_order.id, v_order.tenant_id, v_order.organization_id, v_order.branch_id, v_order.classroom_id,
        'PaymentVerified', v_order.payment_status,
        CASE WHEN v_total_paid >= v_order.total_amount THEN 'Paid' ELSE 'PartiallyPaid' END,
        p_verifier_user_id, p_verifier_name, p_verifier_role,
        format('Payment of %s %s (%s) verified by %s (%s).', v_payment.currency, v_payment.amount, v_payment.method, p_verifier_name, p_verifier_role),
        p_remarks
    );

    RETURN QUERY SELECT TRUE, 'Payment verified successfully.'::TEXT, v_order.id, p_payment_id;
END;
$$;


--
-- Name: fn_verify_submitted_payment(uuid, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_verify_submitted_payment(p_payment_id uuid, p_verified_by character varying, p_remarks text DEFAULT NULL::text) RETURNS TABLE(success boolean, message text, invoice_id uuid, new_amount_paid numeric, new_balance_due numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_payment payments%ROWTYPE;
    v_invoice invoices%ROWTYPE;
    v_effective_payable NUMERIC(14,2);
    v_current_verified NUMERIC(14,2);
BEGIN
    SELECT * INTO v_payment
    FROM payments p
    WHERE p.id = p_payment_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Payment submission not found.', NULL::UUID, 0::NUMERIC(14,2), 0::NUMERIC(14,2);
        RETURN;
    END IF;

    IF v_payment.is_verified OR v_payment.status = 'Completed' THEN
        RETURN QUERY SELECT FALSE, 'This payment has already been verified.', v_payment.invoice_id, 0::NUMERIC(14,2), 0::NUMERIC(14,2);
        RETURN;
    END IF;

    IF v_payment.status <> 'PendingVerification' THEN
        RETURN QUERY SELECT FALSE, 'Only payments awaiting verification can be verified.', v_payment.invoice_id, 0::NUMERIC(14,2), 0::NUMERIC(14,2);
        RETURN;
    END IF;

    SELECT * INTO v_invoice
    FROM invoices inv
    WHERE inv.id = v_payment.invoice_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Associated invoice not found.', v_payment.invoice_id, 0::NUMERIC(14,2), 0::NUMERIC(14,2);
        RETURN;
    END IF;

    IF v_invoice.status IN ('Void', 'Cancelled', 'Draft') THEN
        RETURN QUERY SELECT FALSE, 'Cannot verify payment against a Void, Cancelled, or Draft invoice.', v_invoice.id, v_invoice.amount_paid, 0::NUMERIC(14,2);
        RETURN;
    END IF;

    v_effective_payable := GREATEST(0, v_invoice.total_amount - COALESCE(v_invoice.adjustment_amount, 0));

    SELECT COALESCE(SUM(p.amount), 0) INTO v_current_verified
    FROM payments p
    WHERE p.invoice_id = v_invoice.id
      AND p.status = 'Completed'
      AND p.is_verified = TRUE
      AND p.is_reversed = FALSE;

    IF (v_current_verified + v_payment.amount) > v_effective_payable THEN
        RETURN QUERY SELECT FALSE,
            format('Verified amount exceeds remaining outstanding balance (%s).', (v_effective_payable - v_current_verified)::TEXT),
            v_invoice.id, v_current_verified, GREATEST(0, v_effective_payable - v_current_verified);
        RETURN;
    END IF;

    UPDATE payments
    SET is_verified = TRUE,
        verified_by = p_verified_by,
        verified_at = NOW(),
        status = 'Completed',
        notes = CASE
            WHEN p_remarks IS NOT NULL AND LENGTH(TRIM(p_remarks)) > 0
                THEN COALESCE(notes || E'\nVerification: ', 'Verification: ') || p_remarks
            ELSE notes
        END
    WHERE id = p_payment_id;

    CALL public.sp_recalculate_invoice_balance(v_invoice.id);

    SELECT amount_paid INTO v_current_verified FROM invoices WHERE id = v_invoice.id;

    RETURN QUERY SELECT
        TRUE,
        'Payment verified successfully.',
        v_invoice.id,
        v_current_verified,
        GREATEST(0, v_effective_payable - v_current_verified);
END;
$$;


--
-- Name: sp_acknowledge_teacher_handover(uuid, uuid, uuid, character varying, text); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_acknowledge_teacher_handover(IN p_tenant_id uuid, IN p_handover_id uuid, IN p_user_id uuid, IN p_user_name character varying, IN p_notes text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE teacher_handovers
    SET status = 'Acknowledged',
        acknowledged_at = NOW(),
        acknowledged_by_user_id = p_user_id,
        acknowledged_by_name = p_user_name,
        acknowledgement_notes = p_notes,
        updated_at = NOW()
    WHERE id = p_handover_id AND tenant_id = p_tenant_id;
END;
$$;


