--
-- Name: sp_approve_or_reject_gifting_order(uuid, uuid, character varying, character varying, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sp_approve_or_reject_gifting_order(p_order_id uuid, p_actor_user_id uuid, p_actor_name character varying, p_actor_role character varying, p_decision character varying, p_reason text DEFAULT NULL::text) RETURNS TABLE(success boolean, message text, order_id uuid, order_number character varying, approval_status character varying, approval_decided_by_name character varying, approval_decided_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_order RECORD;
    v_new_approval VARCHAR;
    v_new_payment VARCHAR;
    v_new_fulfilment VARCHAR;
    v_item RECORD;
BEGIN
    -- 1. Pessimistic lock on the order row
    SELECT * INTO v_order
    FROM classroom_gifting_orders
    WHERE id = p_order_id
    FOR UPDATE;

    IF v_order IS NULL THEN
        RETURN QUERY SELECT FALSE, 'Gifting order not found.'::TEXT, NULL::UUID, NULL::VARCHAR, NULL::VARCHAR, NULL::VARCHAR, NULL::TIMESTAMPTZ;
        RETURN;
    END IF;

    -- 2. Concurrency guard: Check if already decided
    IF v_order.approval_status IN ('Approved', 'Rejected') THEN
        RETURN QUERY SELECT FALSE,
            format('Order %s has already been decided (%s by %s on %s).',
                v_order.order_number,
                v_order.approval_status,
                v_order.approval_decided_by_name,
                to_char(v_order.approval_decided_at, 'YYYY-MM-DD HH24:MI:SS')),
            v_order.id, v_order.order_number, v_order.approval_status,
            v_order.approval_decided_by_name, v_order.approval_decided_at;
        RETURN;
    END IF;

    -- 3. Transition statuses
    IF p_decision = 'Approved' THEN
        v_new_approval := 'Approved';
        v_new_payment := 'AwaitingPayment';
        v_new_fulfilment := 'NotStarted';
    ELSIF p_decision = 'Rejected' THEN
        v_new_approval := 'Rejected';
        v_new_payment := 'Cancelled';
        v_new_fulfilment := 'Cancelled';

        -- Release reserved stock back to available stock
        FOR v_item IN SELECT material_product_id, quantity FROM classroom_gifting_order_items WHERE classroom_gifting_order_items.order_id = p_order_id
        LOOP
            UPDATE inventory_balances
            SET available_stock = available_stock + v_item.quantity,
                reserved_stock = GREATEST(0, reserved_stock - v_item.quantity),
                updated_at = NOW()
            WHERE material_product_id = v_item.material_product_id;
        END LOOP;
    ELSE
        RETURN QUERY SELECT FALSE, 'Invalid decision. Must be Approved or Rejected.'::TEXT, v_order.id, v_order.order_number, v_order.approval_status, NULL::VARCHAR, NULL::TIMESTAMPTZ;
        RETURN;
    END IF;

    -- 4. Update the order
    UPDATE classroom_gifting_orders
    SET approval_status = v_new_approval,
        payment_status = v_new_payment,
        fulfilment_status = v_new_fulfilment,
        approval_decided_by_user_id = p_actor_user_id,
        approval_decided_by_name = p_actor_name,
        approval_decided_by_role = p_actor_role,
        approval_decided_at = NOW(),
        rejection_reason = CASE WHEN p_decision = 'Rejected' THEN p_reason ELSE NULL END,
        updated_at = NOW()
    WHERE id = p_order_id;

    -- 5. Record audit event
    INSERT INTO classroom_gifting_audit_events (
        order_id, tenant_id, organization_id, branch_id, classroom_id,
        event_type, previous_status, new_status, actor_user_id, actor_name,
        actor_role, description, notes
    ) VALUES (
        v_order.id, v_order.tenant_id, v_order.organization_id, v_order.branch_id, v_order.classroom_id,
        CASE WHEN p_decision = 'Approved' THEN 'OrderApproved' ELSE 'OrderRejected' END,
        v_order.approval_status, v_new_approval,
        p_actor_user_id, p_actor_name, p_actor_role,
        format('Order %s %s by %s (%s).', v_order.order_number, lower(p_decision), p_actor_name, p_actor_role),
        p_reason
    );

    RETURN QUERY SELECT TRUE,
        format('Order %s successfully %s.', v_order.order_number, lower(p_decision)),
        v_order.id, v_order.order_number, v_new_approval, p_actor_name, NOW();
END;
$$;


--
-- Name: sp_approve_privacy_and_trust(uuid, uuid, text); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_approve_privacy_and_trust(IN p_tenant_id uuid, IN p_child_id uuid, IN p_approved_by_name text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resolved_tenant_id uuid;
BEGIN
    SELECT COALESCE((SELECT tenant_id FROM children WHERE id = p_child_id), p_tenant_id)
    INTO v_resolved_tenant_id;

    INSERT INTO child_consents (id, tenant_id, child_id, consent_type, granted, granted_by, granted_at, version)
    VALUES (gen_random_uuid(), v_resolved_tenant_id, p_child_id, 'PrivacyAndTrust', TRUE, p_approved_by_name, NOW(), '1.0')
    ON CONFLICT (child_id, consent_type)
    DO UPDATE SET granted = TRUE, granted_by = EXCLUDED.granted_by, granted_at = NOW(), version = '1.0';
END;
$$;


--
-- Name: sp_assign_organization_regional_plan(uuid, uuid, uuid, uuid, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_assign_organization_regional_plan(IN p_org_id uuid, IN p_region_id uuid, IN p_plan_id uuid, IN p_tariff_id uuid, IN p_currency character varying DEFAULT NULL::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_region_code VARCHAR(50);
    v_region_name VARCHAR(150);
    v_region_currency VARCHAR(10);
    v_plan_code VARCHAR(50);
    v_plan_name VARCHAR(150);
    v_tariff_currency VARCHAR(10);
    v_old_currency VARCHAR(10);
    v_resolved_currency VARCHAR(10);
    v_max_branches INT;
    v_max_classrooms INT;
    v_max_children INT;
    v_includes_ai BOOLEAN;
    v_tenant_id UUID;
BEGIN
    -- Resolve Region & Region Currency
    SELECT code, name, currency INTO v_region_code, v_region_name, v_region_currency
    FROM pricing_regions
    WHERE id = p_region_id;

    -- Resolve Tariff Currency if tariff is specified
    IF p_tariff_id IS NOT NULL THEN
        SELECT currency INTO v_tariff_currency
        FROM region_plan_tariffs
        WHERE id = p_tariff_id;
    END IF;

    -- Determine Effective Currency: Explicit parameter > Tariff Currency > Region Currency > Existing Org Currency > 'INR'
    SELECT currency, tenant_id INTO v_old_currency, v_tenant_id
    FROM organizations
    WHERE id = p_org_id;

    v_resolved_currency := COALESCE(
        NULLIF(TRIM(p_currency), ''),
        NULLIF(TRIM(v_tariff_currency), ''),
        NULLIF(TRIM(v_region_currency), ''),
        NULLIF(TRIM(v_old_currency), ''),
        'INR'
    );

    -- Resolve Plan limits (fallback standard defaults if not already present)
    IF p_plan_id = '11111111-1111-1111-1111-111111111111'::UUID THEN
        v_plan_code := 'PLAN-SPROUT';
        v_plan_name := 'Sprout (Starter)';
        v_max_branches := 1;
        v_max_classrooms := 3;
        v_max_children := 35;
        v_includes_ai := FALSE;
    ELSIF p_plan_id = '33333333-3333-3333-3333-333333333333'::UUID THEN
        v_plan_code := 'PLAN-CANOPY';
        v_plan_name := 'Canopy (Multi-Branch)';
        v_max_branches := 6;
        v_max_classrooms := 24;
        v_max_children := 300;
        v_includes_ai := TRUE;
    ELSE
        v_plan_code := 'PLAN-BLOOM';
        v_plan_name := 'Bloom (Growth)';
        v_max_branches := 2;
        v_max_classrooms := 8;
        v_max_children := 90;
        v_includes_ai := TRUE;
    END IF;

    -- Track Currency Change History if changed
    IF v_old_currency IS DISTINCT FROM v_resolved_currency THEN
        INSERT INTO public.organization_currency_history (
            organization_id, 
            previous_currency, 
            new_currency, 
            changed_by, 
            reason, 
            effective_from, 
            created_at
        )
        VALUES (
            p_org_id, 
            COALESCE(v_old_currency, 'INR'), 
            v_resolved_currency, 
            'Platform Admin', 
            'Plan & Tariff Configuration Update (' || COALESCE(v_plan_name, '') || ')', 
            NOW(), 
            NOW()
        );
    END IF;

    -- Update Organization with Region, Plan Quotas, Tariff, and Currency
    UPDATE organizations
    SET
        pricing_region_id = p_region_id,
        pricing_region_code = v_region_code,
        pricing_region_name = v_region_name,
        plan_id = p_plan_id,
        plan_code = v_plan_code,
        plan_name = v_plan_name,
        max_branches = v_max_branches,
        max_classrooms = v_max_classrooms,
        max_children = v_max_children,
        includes_ai = v_includes_ai,
        tariff_id = p_tariff_id,
        currency = v_resolved_currency,
        updated_at = NOW()
    WHERE id = p_org_id;

    -- Propagate Currency to tenant_preferences
    IF v_tenant_id IS NOT NULL THEN
        UPDATE tenant_preferences
        SET currency = v_resolved_currency, updated_at = NOW()
        WHERE tenant_id = v_tenant_id;
    END IF;

END;
$$;


--
-- Name: sp_assign_organization_regional_plan(uuid, uuid, uuid, uuid, character varying, character varying, text, uuid, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_assign_organization_regional_plan(IN p_org_id uuid, IN p_region_id uuid, IN p_plan_id uuid, IN p_tariff_id uuid, IN p_currency character varying DEFAULT NULL::character varying, IN p_change_type character varying DEFAULT 'PlatformAdjustment'::character varying, IN p_reason text DEFAULT 'Subscription plan updated'::text, IN p_changed_by_user_id uuid DEFAULT NULL::uuid, IN p_changed_by_email character varying DEFAULT 'platform-admin@enjoyeveryday.com'::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_region_code VARCHAR(50);
    v_region_name VARCHAR(150);
    v_region_currency VARCHAR(10);
    v_plan_code VARCHAR(50);
    v_plan_name VARCHAR(150);
    v_tariff_currency VARCHAR(10);
    v_tariff_name VARCHAR(150);
    v_tariff_price NUMERIC(12,2);
    v_resolved_currency VARCHAR(10);
    v_max_branches INT;
    v_max_classrooms INT;
    v_max_children INT;
    v_includes_ai BOOLEAN;
    v_tenant_id UUID;
    v_prev_plan_id UUID;
    v_prev_plan_code VARCHAR(50);
    v_prev_plan_name VARCHAR(150);
    v_prev_tariff_id UUID;
    v_prev_tariff_name VARCHAR(150);
    v_prev_rate NUMERIC(12,2);
    v_prev_currency VARCHAR(10);
    v_has_history BOOLEAN;
BEGIN
    -- Resolve Region & Region Currency
    SELECT code, name, currency INTO v_region_code, v_region_name, v_region_currency
    FROM pricing_regions
    WHERE id = p_region_id;

    -- Resolve Tariff details if tariff is specified
    IF p_tariff_id IS NOT NULL THEN
        SELECT currency, name, price INTO v_tariff_currency, v_tariff_name, v_tariff_price
        FROM region_plan_tariffs
        WHERE id = p_tariff_id;
    END IF;

    -- Snapshot previous state from organizations
    SELECT
        currency, tenant_id, plan_id, plan_code, plan_name, tariff_id
    INTO
        v_resolved_currency, v_tenant_id, v_prev_plan_id, v_prev_plan_code, v_prev_plan_name, v_prev_tariff_id
    FROM organizations
    WHERE id = p_org_id;

    IF v_prev_tariff_id IS NOT NULL THEN
        SELECT name, price INTO v_prev_tariff_name, v_prev_rate
        FROM region_plan_tariffs
        WHERE id = v_prev_tariff_id;
    END IF;
    v_prev_currency := v_resolved_currency;

    v_resolved_currency := COALESCE(
        NULLIF(TRIM(p_currency), ''),
        NULLIF(TRIM(v_tariff_currency), ''),
        NULLIF(TRIM(v_region_currency), ''),
        NULLIF(TRIM(v_resolved_currency), ''),
        'INR'
    );

    -- Resolve Plan limits
    IF p_plan_id = '11111111-1111-1111-1111-111111111111'::UUID THEN
        v_plan_code := 'PLAN-SPROUT';
        v_plan_name := 'Sprout (Starter)';
        v_max_branches := 1;
        v_max_classrooms := 3;
        v_max_children := 35;
        v_includes_ai := FALSE;
        v_tariff_price := COALESCE(v_tariff_price, 1499);
    ELSIF p_plan_id = '33333333-3333-3333-3333-333333333333'::UUID THEN
        v_plan_code := 'PLAN-CANOPY';
        v_plan_name := 'Canopy (Multi-Branch)';
        v_max_branches := 6;
        v_max_classrooms := 24;
        v_max_children := 300;
        v_includes_ai := TRUE;
        v_tariff_price := COALESCE(v_tariff_price, 6999);
    ELSE
        v_plan_code := 'PLAN-BLOOM';
        v_plan_name := 'Bloom (Growth)';
        v_max_branches := 2;
        v_max_classrooms := 8;
        v_max_children := 90;
        v_includes_ai := TRUE;
        v_tariff_price := COALESCE(v_tariff_price, 2999);
    END IF;

    -- Update Organization with Region, Plan Quotas, Tariff, and Currency
    UPDATE organizations
    SET
        pricing_region_id = p_region_id,
        pricing_region_code = v_region_code,
        pricing_region_name = v_region_name,
        plan_id = p_plan_id,
        plan_code = v_plan_code,
        plan_name = v_plan_name,
        max_branches = v_max_branches,
        max_classrooms = v_max_classrooms,
        max_children = v_max_children,
        includes_ai = v_includes_ai,
        tariff_id = p_tariff_id,
        currency = v_resolved_currency,
        updated_at = NOW()
    WHERE id = p_org_id;

    -- Propagate Currency to tenant_preferences
    IF v_tenant_id IS NOT NULL THEN
        UPDATE tenant_preferences
        SET currency = v_resolved_currency, updated_at = NOW()
        WHERE tenant_id = v_tenant_id;
    END IF;

    -- Record plan history if plan/tariff changed or no history exists yet
    SELECT EXISTS(SELECT 1 FROM organization_plan_history WHERE organization_id = p_org_id) INTO v_has_history;

    IF NOT v_has_history OR v_prev_plan_id IS DISTINCT FROM p_plan_id OR v_prev_tariff_id IS DISTINCT FROM p_tariff_id THEN
        UPDATE organization_plan_history
        SET effective_to = NOW()
        WHERE organization_id = p_org_id AND effective_to IS NULL;

        INSERT INTO organization_plan_history (
            tenant_id,
            organization_id,
            previous_plan_id,
            previous_plan_code,
            previous_plan_name,
            previous_tariff_id,
            previous_tariff_name,
            previous_rate,
            previous_currency,
            new_plan_id,
            new_plan_code,
            new_plan_name,
            new_tariff_id,
            new_tariff_name,
            new_rate,
            new_currency,
            max_branches,
            max_classrooms,
            max_children,
            includes_ai,
            change_type,
            reason,
            changed_by_user_id,
            changed_by_email,
            effective_from
        ) VALUES (
            COALESCE(v_tenant_id, '10000000-0000-0000-0000-000000000001'::UUID),
            p_org_id,
            CASE WHEN v_has_history THEN v_prev_plan_id ELSE NULL END,
            CASE WHEN v_has_history THEN v_prev_plan_code ELSE NULL END,
            CASE WHEN v_has_history THEN v_prev_plan_name ELSE NULL END,
            CASE WHEN v_has_history THEN v_prev_tariff_id ELSE NULL END,
            CASE WHEN v_has_history THEN v_prev_tariff_name ELSE NULL END,
            CASE WHEN v_has_history THEN v_prev_rate ELSE NULL END,
            CASE WHEN v_has_history THEN v_prev_currency ELSE NULL END,
            p_plan_id,
            v_plan_code,
            v_plan_name,
            p_tariff_id,
            COALESCE(v_tariff_name, 'Monthly Standard'),
            COALESCE(v_tariff_price, 0),
            v_resolved_currency,
            v_max_branches,
            v_max_classrooms,
            v_max_children,
            v_includes_ai,
            CASE WHEN NOT v_has_history THEN 'Initial' ELSE COALESCE(NULLIF(p_change_type, ''), 'PlatformAdjustment') END,
            p_reason,
            p_changed_by_user_id,
            p_changed_by_email,
            NOW()
        );
    END IF;
END;
$$;


--
-- Name: sp_assign_organization_role(uuid, uuid, uuid, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_assign_organization_role(IN p_tenant_id uuid, IN p_organization_id uuid, IN p_user_id uuid, IN p_role_name character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_role_id uuid;
    v_template_role_id uuid;
    v_clean_name character varying;
    v_canonical_tenant_id uuid;
BEGIN
    -- Resolve canonical tenant_id from the organization
    SELECT tenant_id INTO v_canonical_tenant_id FROM organizations WHERE id = p_organization_id;
    IF v_canonical_tenant_id IS NULL THEN
        v_canonical_tenant_id := p_tenant_id;
    END IF;

    -- 1. Ensure organization membership exists for this user and organization
    INSERT INTO organization_memberships (user_id, organization_id, tenant_id, status, created_at, updated_at)
    VALUES (p_user_id, p_organization_id, v_canonical_tenant_id, 'Active', NOW(), NOW())
    ON CONFLICT (user_id, organization_id) DO UPDATE
    SET status = 'Active', tenant_id = v_canonical_tenant_id, updated_at = NOW();

    -- Normalize role name
    v_clean_name := REPLACE(p_role_name, ' ', '');

    -- 2. Find matching role for this tenant
    SELECT id INTO v_role_id
    FROM roles
    WHERE tenant_id = v_canonical_tenant_id AND (name = p_role_name OR name = v_clean_name)
    LIMIT 1;

    -- If not found under this tenant, see if there's a template/global role or any role with this name, and copy it to this tenant
    IF v_role_id IS NULL THEN
        SELECT id INTO v_template_role_id
        FROM roles
        WHERE name = p_role_name OR name = v_clean_name
        LIMIT 1;

        IF v_template_role_id IS NOT NULL THEN
            INSERT INTO roles (id, tenant_id, name, description, scope_type, created_at)
            SELECT gen_random_uuid(), v_canonical_tenant_id, r.name, r.description, 'Organization', NOW()
            FROM roles r
            WHERE r.id = v_template_role_id
            RETURNING id INTO v_role_id;

            INSERT INTO role_permissions (role_id, permission_id)
            SELECT v_role_id, rp.permission_id
            FROM role_permissions rp
            WHERE rp.role_id = v_template_role_id
            ON CONFLICT DO NOTHING;
        END IF;
    END IF;

    -- 3. Assign role to user in user_organization_roles
    IF v_role_id IS NOT NULL THEN
        INSERT INTO user_organization_roles (user_id, role_id, organization_id, tenant_id)
        VALUES (p_user_id, v_role_id, p_organization_id, v_canonical_tenant_id)
        ON CONFLICT (user_id, role_id, organization_id) DO UPDATE
        SET tenant_id = v_canonical_tenant_id;
    END IF;
END;
$$;


--
-- Name: sp_assign_platform_role(uuid, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_assign_platform_role(IN p_user_id uuid, IN p_role_name character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO user_roles (user_id, role_id)
    SELECT p_user_id, id
    FROM roles
    WHERE name = p_role_name AND tenant_id IS NULL AND scope_type = 'Platform'
    ON CONFLICT DO NOTHING;
END;
$$;


