-- Name: sp_assign_substitute_coverage(uuid, uuid, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_assign_substitute_coverage(IN p_tenant_id uuid, IN p_leave_id uuid, IN p_substitute_teacher_id uuid)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE staff_leaves
    SET substitute_teacher_id = p_substitute_teacher_id,
        coverage_status = 'Covered'
    WHERE tenant_id = p_tenant_id AND id = p_leave_id;
END;
$$;


--
-- Name: sp_assign_user_branch(uuid, uuid, uuid, uuid, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_assign_user_branch(IN p_tenant_id uuid, IN p_organization_id uuid, IN p_branch_id uuid, IN p_user_id uuid, IN p_assigned_by uuid DEFAULT NULL::uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_canonical_tenant_id uuid;
BEGIN
    -- Resolve canonical tenant_id from the organization to guarantee FK integrity
    SELECT tenant_id INTO v_canonical_tenant_id FROM organizations WHERE id = p_organization_id;
    IF v_canonical_tenant_id IS NULL THEN
        v_canonical_tenant_id := p_tenant_id;
    END IF;

    INSERT INTO user_branch_assignments (user_id, branch_id, organization_id, tenant_id, assigned_by, created_at, revoked_at)
    VALUES (p_user_id, p_branch_id, p_organization_id, v_canonical_tenant_id, p_assigned_by, NOW(), NULL)
    ON CONFLICT (user_id, branch_id) DO UPDATE
    SET revoked_at = NULL,
        tenant_id = v_canonical_tenant_id,
        organization_id = p_organization_id,
        assigned_by = COALESCE(p_assigned_by, user_branch_assignments.assigned_by);
END;
$$;


--
-- Name: sp_close_branch_day(uuid, uuid, date, uuid, time without time zone, integer, integer, boolean, text); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_close_branch_day(IN p_tenant_id uuid, IN p_branch_id uuid, IN p_date date, IN p_user_id uuid, IN p_checkout_time time without time zone, INOUT p_open_classrooms_count integer DEFAULT 0, INOUT p_teachers_clocked_out integer DEFAULT 0, INOUT p_success boolean DEFAULT false, INOUT p_message text DEFAULT ''::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_time TIME := COALESCE(p_checkout_time, '19:00:00'::TIME);
    v_open_room_names TEXT;
BEGIN
    -- 1. Check if any classrooms are still Open
    SELECT 
        COUNT(*),
        STRING_AGG(c.name, ', ')
    INTO 
        p_open_classrooms_count,
        v_open_room_names
    FROM public.classrooms c
    JOIN public.classroom_daily_operations cdo 
      ON c.id = cdo.classroom_id 
     AND cdo.tenant_id = p_tenant_id 
     AND cdo.operation_date = p_date
    WHERE c.branch_id = p_branch_id
      AND c.is_active = TRUE
      AND cdo.status = 'Open';

    IF p_open_classrooms_count > 0 THEN
        p_success := FALSE;
        p_message := FORMAT('Cannot close branch. %s classroom(s) still open: %s. Teachers must close their rooms first.', p_open_classrooms_count, v_open_room_names);
        RETURN;
    END IF;

    -- 2. Clock out remaining teachers in the branch
    WITH clocked_out AS (
        UPDATE public.teacher_attendance
        SET 
            clock_out_time = v_time,
            updated_at = NOW()
        WHERE tenant_id = p_tenant_id
          AND branch_id = p_branch_id
          AND attendance_date = p_date
          AND clock_out_time IS NULL
        RETURNING id
    )
    SELECT COUNT(*) INTO p_teachers_clocked_out FROM clocked_out;

    -- 3. Mark branch closed
    UPDATE public.branch_daily_operations
    SET
        status = 'Closed',
        closed_at = NOW(),
        closed_by_user_id = p_user_id,
        summary_json = jsonb_build_object(
            'teachers_clocked_out_at_close', p_teachers_clocked_out,
            'closed_at_time', v_time::text
        ),
        updated_at = NOW()
    WHERE tenant_id = p_tenant_id
      AND branch_id = p_branch_id
      AND operation_date = p_date;

    IF NOT FOUND THEN
        INSERT INTO public.branch_daily_operations (
            tenant_id, branch_id, operation_date, status, closed_at, closed_by_user_id, updated_at
        ) VALUES (
            p_tenant_id, p_branch_id, p_date, 'Closed', NOW(), p_user_id, NOW()
        );
    END IF;

    p_success := TRUE;
    p_message := FORMAT('Branch successfully closed for the day. %s staff clocked out.', p_teachers_clocked_out);
END;
$$;


--
-- Name: sp_close_classroom_day(uuid, uuid, date, uuid, time without time zone, integer, integer, boolean, text); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_close_classroom_day(IN p_tenant_id uuid, IN p_classroom_id uuid, IN p_date date, IN p_user_id uuid, IN p_checkout_time time without time zone, INOUT p_children_checked_out integer DEFAULT 0, INOUT p_activities_closed integer DEFAULT 0, INOUT p_success boolean DEFAULT false, INOUT p_message text DEFAULT ''::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_branch_id UUID;
    v_time TIME := COALESCE(p_checkout_time, '18:30:00'::TIME);
    v_summary JSONB;
BEGIN
    SELECT branch_id INTO v_branch_id
    FROM public.classrooms
    WHERE id = p_classroom_id;

    -- 1. Check out remaining present children
    WITH checked_out AS (
        UPDATE public.child_attendance
        SET 
            status = 'CheckedOut',
            departure_time = v_time,
            departure_verified_by_user_id = p_user_id,
            updated_at = NOW()
        WHERE tenant_id = p_tenant_id 
          AND classroom_id = p_classroom_id 
          AND attendance_date = p_date
          AND status = 'Present'
          AND departure_time IS NULL
        RETURNING id
    )
    SELECT COUNT(*) INTO p_children_checked_out FROM checked_out;

    -- 2. Complete open / active activity sessions
    WITH closed_sessions AS (
        UPDATE public.experience_sessions
        SET 
            status = 'Completed',
            end_time = COALESCE(end_time, v_time),
            updated_at = NOW()
        WHERE tenant_id = p_tenant_id
          AND classroom_id = p_classroom_id
          AND session_date = p_date
          AND status IN ('InProgress', 'Active', 'Planned')
        RETURNING id
    )
    SELECT COUNT(*) INTO p_activities_closed FROM closed_sessions;

    -- 3. Construct summary json
    v_summary := jsonb_build_object(
        'children_checked_out_at_close', p_children_checked_out,
        'activities_auto_completed', p_activities_closed,
        'closed_at_time', v_time::text
    );

    -- 4. Mark classroom closed
    UPDATE public.classroom_daily_operations
    SET
        status = 'Closed',
        closed_at = NOW(),
        closed_by_user_id = p_user_id,
        summary_json = v_summary,
        updated_at = NOW()
    WHERE tenant_id = p_tenant_id
      AND classroom_id = p_classroom_id
      AND operation_date = p_date;

    IF NOT FOUND THEN
        INSERT INTO public.classroom_daily_operations (
            tenant_id, branch_id, classroom_id, operation_date, status, closed_at, closed_by_user_id, summary_json, updated_at
        ) VALUES (
            p_tenant_id, v_branch_id, p_classroom_id, p_date, 'Closed', NOW(), p_user_id, v_summary, NOW()
        );
    END IF;

    p_success := TRUE;
    p_message := FORMAT('Classroom closed. %s children checked out and %s activities completed.', p_children_checked_out, p_activities_closed);
END;
$$;


--
-- Name: sp_close_end_of_day_activities(uuid, uuid[], interval); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_close_end_of_day_activities(IN p_tenant_id uuid, IN p_schedule_ids uuid[], IN p_end_time interval)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE experience_schedules
    SET status = 'Completed',
        preparation_notes = CASE WHEN preparation_notes IS NULL OR preparation_notes = '' THEN 'System Auto-Closed at End of Day'
                                 WHEN preparation_notes LIKE '%System Auto-Closed%' THEN preparation_notes
                                 ELSE preparation_notes || ' [System Auto-Closed]' END,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = ANY(p_schedule_ids);

    UPDATE experience_sessions
    SET status = 'Completed',
        end_time = p_end_time::time,
        actual_notes = CASE WHEN actual_notes IS NULL OR actual_notes = '' THEN 'System Auto-Closed at End of Day'
                            WHEN actual_notes LIKE '%System Auto-Closed%' THEN actual_notes
                            ELSE actual_notes || ' [System Auto-Closed]' END,
        updated_at = CURRENT_TIMESTAMP
    WHERE tenant_id = p_tenant_id
      AND (
          experience_schedule_id = ANY(p_schedule_ids)
          OR (status NOT IN ('Completed', 'Cancelled', 'Finished') AND session_date = CURRENT_DATE)
      );
END;
$$;


--
-- Name: sp_close_end_of_day_activities(uuid, uuid[], time without time zone); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_close_end_of_day_activities(IN p_tenant_id uuid, IN p_schedule_ids uuid[], IN p_end_time time without time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    CALL public.sp_close_end_of_day_activities(p_tenant_id, p_schedule_ids, p_end_time::interval);
END;
$$;


--
-- Name: sp_close_end_of_day_children(interval, uuid, uuid[]); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_close_end_of_day_children(IN p_departure interval, IN p_user_id uuid, IN p_ids uuid[])
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE child_attendance
    SET departure_time = p_departure::time,
        status = 'CheckedOut',
        pickup_person_name = 'System Auto-Closed',
        pickup_person_relationship = 'System Process',
        pickup_verification_method = 'System Auto-Closed',
        pickup_notes = CASE WHEN pickup_notes IS NULL OR pickup_notes = '' THEN 'System auto-checkout at End of Day'
                            ELSE pickup_notes || ' · System auto-checkout at End of Day' END,
        departure_verified_by_user_id = CASE WHEN p_user_id = '00000000-0000-0000-0000-000000000000'::uuid THEN NULL ELSE p_user_id END,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = ANY(p_ids);
END;
$$;


--
-- Name: sp_close_end_of_day_children(time without time zone, uuid, uuid[]); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_close_end_of_day_children(IN p_departure time without time zone, IN p_user_id uuid, IN p_ids uuid[])
    LANGUAGE plpgsql
    AS $$
BEGIN
    CALL public.sp_close_end_of_day_children(p_departure::interval, p_user_id, p_ids);
END;
$$;


--
-- Name: sp_close_end_of_day_events(uuid[]); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_close_end_of_day_events(IN p_ids uuid[])
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE events
    SET status = 'Completed',
        description = CASE WHEN description IS NULL OR description = '' THEN 'System Auto-Closed at End of Day'
                           WHEN description LIKE '%System Auto-Closed%' THEN description
                           ELSE description || ' [System Auto-Closed]' END,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = ANY(p_ids);
END;
$$;


--
-- Name: sp_close_end_of_day_teachers(interval, uuid[]); Type: PROCEDURE; Schema: public; Owner: -
