--
-- Name: sp_delete_teacher(uuid, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_delete_teacher(IN p_tenant_id uuid, IN p_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_user_id UUID;
    v_org_id UUID;
BEGIN
    SELECT user_id INTO v_user_id FROM teachers WHERE id = p_id;
    SELECT id INTO v_org_id FROM organizations WHERE tenant_id = p_tenant_id LIMIT 1;

    UPDATE teachers SET status = 'Inactive', updated_at = NOW()
    WHERE id = p_id AND tenant_id = p_tenant_id;

    IF v_user_id IS NOT NULL AND v_org_id IS NOT NULL THEN
        CALL sp_remove_user_from_organization(p_tenant_id, v_org_id, v_user_id);
    ELSIF v_user_id IS NOT NULL THEN
        UPDATE users SET is_active = FALSE, updated_at = NOW() WHERE id = v_user_id;
    END IF;
END;
$$;


--
-- Name: sp_delete_teacher(uuid, uuid, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_delete_teacher(IN p_tenant_id uuid, IN p_id uuid, IN p_organization_id uuid DEFAULT NULL::uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_user_id UUID;
    v_org_id UUID := p_organization_id;
BEGIN
    SELECT user_id INTO v_user_id FROM teachers WHERE id = p_id;

    IF v_org_id IS NULL THEN
        SELECT id INTO v_org_id FROM organizations WHERE tenant_id = p_tenant_id LIMIT 1;
    END IF;

    UPDATE teachers SET status = 'Inactive', updated_at = NOW()
    WHERE id = p_id AND tenant_id = p_tenant_id;

    IF v_user_id IS NOT NULL AND v_org_id IS NOT NULL THEN
        CALL sp_remove_user_from_organization(p_tenant_id, v_org_id, v_user_id);
    ELSIF v_user_id IS NOT NULL THEN
        UPDATE users SET is_active = FALSE, updated_at = NOW() WHERE id = v_user_id;
    END IF;
END;
$$;


--
-- Name: sp_delete_user(uuid, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_delete_user(IN p_tenant_id uuid, IN p_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_org_id UUID;
BEGIN
    SELECT id INTO v_org_id FROM organizations WHERE tenant_id = p_tenant_id LIMIT 1;

    IF v_org_id IS NOT NULL THEN
        CALL sp_remove_user_from_organization(p_tenant_id, v_org_id, p_id);
    ELSE
        UPDATE users SET is_active = FALSE, updated_at = NOW() WHERE id = p_id;
        UPDATE teachers SET status = 'Inactive', updated_at = NOW() WHERE user_id = p_id;
        UPDATE organization_memberships SET status = 'Inactive', updated_at = NOW() WHERE user_id = p_id;
        DELETE FROM user_organization_roles WHERE user_id = p_id;
        UPDATE user_branch_assignments SET revoked_at = NOW() WHERE user_id = p_id AND revoked_at IS NULL;
        DELETE FROM classroom_teachers WHERE user_id = p_id;
    END IF;
END;
$$;


--
-- Name: sp_dispatch_teacher_to_classroom(uuid, uuid, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_dispatch_teacher_to_classroom(IN p_tenant_id uuid, IN p_classroom_id uuid, IN p_user_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_canonical_tenant_id uuid;
BEGIN
    SELECT tenant_id INTO v_canonical_tenant_id FROM classrooms WHERE id = p_classroom_id;
    IF v_canonical_tenant_id IS NULL THEN
        v_canonical_tenant_id := p_tenant_id;
    END IF;

    INSERT INTO classroom_teachers (id, tenant_id, classroom_id, user_id, is_primary)
    VALUES (gen_random_uuid(), v_canonical_tenant_id, p_classroom_id, p_user_id, FALSE)
    ON CONFLICT (classroom_id, user_id) DO UPDATE
    SET tenant_id = v_canonical_tenant_id;
END;
$$;


