--
-- Name: sp_open_branch_day(uuid, uuid, date, uuid, boolean, text); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_open_branch_day(IN p_tenant_id uuid, IN p_branch_id uuid, IN p_date date, IN p_user_id uuid, INOUT p_success boolean DEFAULT false, INOUT p_message text DEFAULT ''::text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO public.branch_daily_operations (
        tenant_id, branch_id, operation_date, status, opened_at, opened_by_user_id, updated_at
    )
    VALUES (
        p_tenant_id, p_branch_id, p_date, 'Open', NOW(), p_user_id, NOW()
    )
    ON CONFLICT (tenant_id, branch_id, operation_date)
    DO UPDATE SET
        status = 'Open',
        opened_at = COALESCE(public.branch_daily_operations.opened_at, NOW()),
        opened_by_user_id = COALESCE(public.branch_daily_operations.opened_by_user_id, p_user_id),
        closed_at = NULL,
        closed_by_user_id = NULL,
        updated_at = NOW();

    p_success := TRUE;
    p_message := 'Branch successfully opened for operations.';
END;
$$;


--
-- Name: sp_open_classroom_day(uuid, uuid, date, uuid, boolean, text); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_open_classroom_day(IN p_tenant_id uuid, IN p_classroom_id uuid, IN p_date date, IN p_user_id uuid, INOUT p_success boolean DEFAULT false, INOUT p_message text DEFAULT ''::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_branch_id UUID;
    v_branch_status VARCHAR(20);
BEGIN
    -- Resolve branch for this classroom
    SELECT branch_id INTO v_branch_id
    FROM public.classrooms
    WHERE id = p_classroom_id;

    IF v_branch_id IS NULL THEN
        p_success := FALSE;
        p_message := 'Classroom not found or not assigned to a branch.';
        RETURN;
    END IF;

    -- Check branch daily status
    SELECT status INTO v_branch_status
    FROM public.branch_daily_operations
    WHERE tenant_id = p_tenant_id AND branch_id = v_branch_id AND operation_date = p_date;

    IF v_branch_status IS NULL OR v_branch_status != 'Open' THEN
        p_success := FALSE;
        p_message := 'Cannot open classroom. The Branch Admin must first open the branch for operations today.';
        RETURN;
    END IF;

    -- Open classroom
    INSERT INTO public.classroom_daily_operations (
        tenant_id, branch_id, classroom_id, operation_date, status, opened_at, opened_by_user_id, updated_at
    )
    VALUES (
        p_tenant_id, v_branch_id, p_classroom_id, p_date, 'Open', NOW(), p_user_id, NOW()
    )
    ON CONFLICT (tenant_id, classroom_id, operation_date)
    DO UPDATE SET
        status = 'Open',
        opened_at = COALESCE(public.classroom_daily_operations.opened_at, NOW()),
        opened_by_user_id = COALESCE(public.classroom_daily_operations.opened_by_user_id, p_user_id),
        closed_at = NULL,
        closed_by_user_id = NULL,
        updated_at = NOW();

    p_success := TRUE;
    p_message := 'Classroom successfully opened for daily learning and care.';
END;
$$;


--
-- Name: sp_promote_teacher_to_lead(uuid, uuid, uuid, uuid, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sp_promote_teacher_to_lead(p_tenant_id uuid, p_organization_id uuid, p_branch_id uuid, p_user_id uuid, p_classroom_ids uuid[], p_promoted_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_canonical_tenant_id uuid;
    v_lead_role_id uuid;
    v_template_role_id uuid;
    v_cid uuid;
    v_classroom_tenant_id uuid;
BEGIN
    -- 1. Resolve canonical tenant_id from organization
    SELECT tenant_id INTO v_canonical_tenant_id FROM organizations WHERE id = p_organization_id;
    IF v_canonical_tenant_id IS NULL THEN
        v_canonical_tenant_id := p_tenant_id;
    END IF;

    -- 2. Ensure active organization membership
    INSERT INTO organization_memberships (user_id, organization_id, tenant_id, status, created_at, updated_at)
    VALUES (p_user_id, p_organization_id, v_canonical_tenant_id, 'Active', NOW(), NOW())
    ON CONFLICT (user_id, organization_id) DO UPDATE
    SET status = 'Active', updated_at = NOW();

    -- 3. Find or ensure LeadTeacher role exists for this tenant
    SELECT id INTO v_lead_role_id
    FROM roles
    WHERE tenant_id = v_canonical_tenant_id AND (name = 'LeadTeacher' OR name = 'Lead Teacher')
    LIMIT 1;

    IF v_lead_role_id IS NULL THEN
        SELECT id INTO v_template_role_id
        FROM roles
        WHERE (name = 'LeadTeacher' OR name = 'Lead Teacher')
        ORDER BY created_at ASC
        LIMIT 1;

        IF v_template_role_id IS NOT NULL THEN
            INSERT INTO roles (id, tenant_id, name, description, role_rank, is_system_role, scope_type, created_at, updated_at)
            SELECT
                gen_random_uuid(),
                v_canonical_tenant_id,
                'LeadTeacher',
                r.description,
                COALESCE(r.role_rank, 4),
                r.is_system_role,
                COALESCE(r.scope_type, 'Organization'),
                NOW(),
                NOW()
            FROM roles r
            WHERE r.id = v_template_role_id
            RETURNING id INTO v_lead_role_id;
        ELSE
            INSERT INTO roles (id, tenant_id, name, description, role_rank, is_system_role, scope_type, created_at, updated_at)
            VALUES (
                gen_random_uuid(),
                v_canonical_tenant_id,
                'LeadTeacher',
                'Lead Teacher coordinating classroom delivery and supporting educators',
                4,
                true,
                'Organization',
                NOW(),
                NOW()
            )
            RETURNING id INTO v_lead_role_id;
        END IF;
    END IF;

    -- 4. Assign Lead Teacher role in user_organization_roles
    INSERT INTO user_organization_roles (id, tenant_id, organization_id, user_id, role_id)
    VALUES (gen_random_uuid(), v_canonical_tenant_id, p_organization_id, p_user_id, v_lead_role_id)
    ON CONFLICT DO NOTHING;

    -- 5. Remove lower/generic educator roles in this organization context
    DELETE FROM user_organization_roles uor
    USING roles r
    WHERE uor.role_id = r.id
      AND uor.user_id = p_user_id
      AND uor.organization_id = p_organization_id
      AND r.name IN ('Teacher', 'DaycareTeacher', 'ClassroomTeacher', 'AssistantTeacher')
      AND uor.role_id <> v_lead_role_id;

    -- 6. Ensure active branch assignment
    INSERT INTO user_branch_assignments (user_id, branch_id, tenant_id, organization_id, assigned_by, created_at)
    VALUES (p_user_id, p_branch_id, v_canonical_tenant_id, p_organization_id, p_promoted_by, NOW())
    ON CONFLICT (user_id, branch_id) DO UPDATE
    SET revoked_at = NULL,
        tenant_id = v_canonical_tenant_id,
        organization_id = p_organization_id,
        assigned_by = COALESCE(p_promoted_by, user_branch_assignments.assigned_by);

    -- 7. Synchronize classroom assignments for this branch:
    -- Remove old classrooms in THIS branch that are not in p_classroom_ids
    DELETE FROM classroom_teachers ct
    USING classrooms c
    WHERE ct.classroom_id = c.id
      AND ct.user_id = p_user_id
      AND c.branch_id = p_branch_id
      AND (p_classroom_ids IS NULL OR NOT (c.id = ANY(p_classroom_ids)));

    -- Add/update all newly selected classrooms with is_primary = TRUE
    IF p_classroom_ids IS NOT NULL AND array_length(p_classroom_ids, 1) > 0 THEN
        FOREACH v_cid IN ARRAY p_classroom_ids
        LOOP
            SELECT tenant_id INTO v_classroom_tenant_id FROM classrooms WHERE id = v_cid;
            IF v_classroom_tenant_id IS NULL THEN
                v_classroom_tenant_id := v_canonical_tenant_id;
            END IF;

            INSERT INTO classroom_teachers (id, tenant_id, classroom_id, user_id, is_primary)
            VALUES (gen_random_uuid(), v_classroom_tenant_id, v_cid, p_user_id, TRUE)
            ON CONFLICT (classroom_id, user_id) DO UPDATE
            SET tenant_id = v_classroom_tenant_id,
                is_primary = TRUE;
        END LOOP;
    END IF;
END;
$$;


--
-- Name: sp_promote_teacher_to_lead(uuid, uuid, uuid, uuid, uuid, uuid[]); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_promote_teacher_to_lead(IN p_tenant_id uuid, IN p_organization_id uuid, IN p_branch_id uuid, IN p_user_id uuid, IN p_promoted_by uuid, IN p_classroom_ids uuid[])
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_canonical_tenant_id uuid;
    v_lead_role_id uuid;
    v_template_role_id uuid;
    v_cid uuid;
    v_classroom_tenant_id uuid;
BEGIN
    -- 1. Resolve canonical tenant_id from organization
    SELECT tenant_id INTO v_canonical_tenant_id FROM organizations WHERE id = p_organization_id;
    IF v_canonical_tenant_id IS NULL THEN
        v_canonical_tenant_id := p_tenant_id;
    END IF;

    -- 2. Validate active organization membership
    IF NOT EXISTS (
        SELECT 1 FROM organization_memberships 
        WHERE user_id = p_user_id AND organization_id = p_organization_id AND status = 'Active'
    ) THEN
        RAISE EXCEPTION 'User does not have an active membership in organization %', p_organization_id;
    END IF;

    -- 3. Find or ensure LeadTeacher role exists for this tenant
    SELECT id INTO v_lead_role_id
    FROM roles
    WHERE tenant_id = v_canonical_tenant_id AND (name = 'LeadTeacher' OR name = 'Lead Teacher')
    LIMIT 1;

    IF v_lead_role_id IS NULL THEN
        SELECT id INTO v_template_role_id
        FROM roles
        WHERE name = 'LeadTeacher' OR name = 'Lead Teacher'
        LIMIT 1;

        IF v_template_role_id IS NOT NULL THEN
            INSERT INTO roles (id, tenant_id, name, description, scope_type, created_at)
            SELECT gen_random_uuid(), v_canonical_tenant_id, r.name, r.description, COALESCE(r.scope_type, 'Organization'), NOW()
            FROM roles r
            WHERE r.id = v_template_role_id
            RETURNING id INTO v_lead_role_id;

            INSERT INTO role_permissions (role_id, permission_id)
            SELECT v_lead_role_id, rp.permission_id
            FROM role_permissions rp
            WHERE rp.role_id = v_template_role_id
            ON CONFLICT DO NOTHING;
        ELSE
            -- Fallback: create role with standard LeadTeacher permissions
            INSERT INTO roles (id, tenant_id, name, description, scope_type, created_at)
            VALUES (gen_random_uuid(), v_canonical_tenant_id, 'LeadTeacher', 'Lead Educator with classroom coordination authority', 'Organization', NOW())
            RETURNING id INTO v_lead_role_id;
        END IF;
    END IF;

    -- 4. Remove previous lower teacher roles in this organization
    DELETE FROM user_organization_roles uor
    USING roles r
    WHERE uor.role_id = r.id
      AND uor.user_id = p_user_id
      AND uor.organization_id = p_organization_id
      AND r.name IN ('Teacher', 'ClassroomTeacher', 'DaycareTeacher', 'AssistantTeacher');

    -- 5. Assign LeadTeacher role for this organization
    IF v_lead_role_id IS NOT NULL THEN
        INSERT INTO user_organization_roles (user_id, role_id, organization_id, tenant_id)
        VALUES (p_user_id, v_lead_role_id, p_organization_id, v_canonical_tenant_id)
        ON CONFLICT (user_id, role_id, organization_id) DO UPDATE
        SET tenant_id = v_canonical_tenant_id;
    END IF;

    -- 6. Ensure user branch assignment is active for this branch
    IF p_branch_id IS NOT NULL THEN
        INSERT INTO user_branch_assignments (user_id, branch_id, organization_id, tenant_id, assigned_by, created_at, revoked_at)
        VALUES (p_user_id, p_branch_id, p_organization_id, v_canonical_tenant_id, p_promoted_by, NOW(), NULL)
        ON CONFLICT (user_id, branch_id) DO UPDATE
        SET revoked_at = NULL,
            tenant_id = v_canonical_tenant_id,
            organization_id = p_organization_id,
            assigned_by = COALESCE(p_promoted_by, user_branch_assignments.assigned_by);
    END IF;

    -- 7. Synchronize classroom assignments for this branch:
    -- Remove old classrooms in THIS branch that are not in p_classroom_ids
    DELETE FROM classroom_teachers ct
    USING classrooms c
    WHERE ct.classroom_id = c.id
      AND ct.user_id = p_user_id
      AND c.branch_id = p_branch_id
      AND (p_classroom_ids IS NULL OR NOT (c.id = ANY(p_classroom_ids)));

    -- Add all newly selected classrooms
    IF p_classroom_ids IS NOT NULL AND array_length(p_classroom_ids, 1) > 0 THEN
        FOREACH v_cid IN ARRAY p_classroom_ids
        LOOP
            SELECT tenant_id INTO v_classroom_tenant_id FROM classrooms WHERE id = v_cid;
            IF v_classroom_tenant_id IS NULL THEN
                v_classroom_tenant_id := v_canonical_tenant_id;
            END IF;

            INSERT INTO classroom_teachers (id, tenant_id, classroom_id, user_id, is_primary)
            VALUES (gen_random_uuid(), v_classroom_tenant_id, v_cid, p_user_id, FALSE)
            ON CONFLICT (classroom_id, user_id) DO UPDATE
            SET tenant_id = v_classroom_tenant_id;
        END LOOP;
    END IF;
END;
$$;


--
-- Name: sp_provision_platform_organization(uuid, character varying, character varying, character varying, integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_provision_platform_organization(IN p_org_id uuid, IN p_name character varying, IN p_location character varying, IN p_admin_email character varying, IN p_branch_count integer DEFAULT 1)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_raw_slug VARCHAR;
    v_slug VARCHAR;
    v_slug_count INT;
    v_existing_user_id UUID;
    v_existing_tenant_id UUID;
    v_admin_user_id UUID;
    v_derived_name VARCHAR;
    v_branches_to_create INT;
    v_i INT;
    v_branch_id UUID;
    v_branch_name VARCHAR;
    v_branch_loc VARCHAR;
    v_role_id UUID;
BEGIN
    v_raw_slug := trim(both '-' from regexp_replace(lower(p_name), '[^a-z0-9]+', '-', 'g'));
    IF v_raw_slug IS NULL OR v_raw_slug = '' THEN
        v_slug := 'org-' || substring(p_org_id::text, 1, 8);
    ELSE
        v_slug := v_raw_slug;
    END IF;

    SELECT COUNT(1) INTO v_slug_count FROM tenants WHERE slug = v_slug;
    IF v_slug_count > 0 THEN
        v_slug := v_slug || '-' || substring(p_org_id::text, 1, 4);
    END IF;

    INSERT INTO tenants (id, name, slug) 
    VALUES (p_org_id, p_name, v_slug) 
    ON CONFLICT (id) DO NOTHING;

    SELECT id, tenant_id INTO v_existing_user_id, v_existing_tenant_id 
    FROM users 
    WHERE LOWER(email) = LOWER(trim(p_admin_email)) OR normalized_email = UPPER(trim(p_admin_email)) 
    LIMIT 1;

    IF v_existing_user_id IS NOT NULL THEN
        v_admin_user_id := v_existing_user_id;
        IF v_existing_tenant_id = '10000000-0000-0000-0000-000000000001'::uuid THEN
            UPDATE users SET tenant_id = p_org_id WHERE id = v_admin_user_id;
        END IF;
    ELSE
        v_admin_user_id := gen_random_uuid();
        v_derived_name := initcap(split_part(split_part(trim(p_admin_email), '@', 1), '.', 1));
        IF v_derived_name IS NULL OR v_derived_name = '' THEN
            v_derived_name := 'Daycare Director';
        END IF;

        INSERT INTO users (id, tenant_id, email, normalized_email, email_confirmed, first_name, last_name, display_name, is_active)
        VALUES (v_admin_user_id, p_org_id, trim(p_admin_email), UPPER(trim(p_admin_email)), TRUE, 'Admin', v_derived_name, v_derived_name, TRUE)
        ON CONFLICT (normalized_email) DO NOTHING;
    END IF;

    INSERT INTO organizations (id, tenant_id, name, location, is_active)
    VALUES (p_org_id, p_org_id, p_name, p_location, TRUE)
    ON CONFLICT (id) DO NOTHING;

    v_branches_to_create := GREATEST(1, p_branch_count);
    FOR v_i IN 1..v_branches_to_create LOOP
        v_branch_id := gen_random_uuid();
        IF v_i = 1 THEN
            v_branch_name := 'Main Campus';
        ELSIF v_i = 2 THEN
            v_branch_name := 'Annex Campus';
        ELSE
            v_branch_name := 'Campus ' || v_i;
        END IF;

        IF p_location IS NOT NULL AND trim(p_location) <> '' THEN
            v_branch_loc := p_location;
        ELSE
            v_branch_loc := 'Main Branch';
        END IF;

        INSERT INTO branches (id, tenant_id, organization_id, name, location, is_active)
        VALUES (v_branch_id, p_org_id, p_org_id, v_branch_name, v_branch_loc, TRUE)
        ON CONFLICT (id) DO NOTHING;
    END LOOP;

    IF v_admin_user_id IS NOT NULL THEN
        INSERT INTO organization_memberships (user_id, organization_id, tenant_id, status)
        VALUES (v_admin_user_id, p_org_id, p_org_id, 'Active')
        ON CONFLICT (user_id, organization_id) DO NOTHING;

        SELECT id INTO v_role_id 
        FROM roles 
        WHERE name IN ('OrganizationAdmin', 'OrganizationOwner') 
          AND (tenant_id = p_org_id OR tenant_id IS NULL) 
        ORDER BY tenant_id NULLS LAST 
        LIMIT 1;

        IF v_role_id IS NOT NULL THEN
            INSERT INTO user_organization_roles (user_id, role_id, organization_id, tenant_id)
            VALUES (v_admin_user_id, v_role_id, p_org_id, p_org_id)
            ON CONFLICT (user_id, role_id, organization_id) DO NOTHING;
        END IF;
    END IF;
END;
$$;


--
-- Name: sp_recalculate_invoice_balance(uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_recalculate_invoice_balance(IN p_invoice_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_paid NUMERIC(14,2);
    v_pending NUMERIC(14,2);
    v_total_amount NUMERIC(14,2);
    v_adjustment NUMERIC(14,2);
    v_effective_payable NUMERIC(14,2);
BEGIN
    SELECT COALESCE(SUM(amount), 0)
    INTO v_total_paid
    FROM payments
    WHERE invoice_id = p_invoice_id
      AND status = 'Completed'
      AND is_verified = TRUE
      AND is_reversed = FALSE;

    SELECT COALESCE(SUM(amount), 0)
    INTO v_pending
    FROM payments
    WHERE invoice_id = p_invoice_id
      AND status = 'PendingVerification'
      AND is_reversed = FALSE;

    SELECT total_amount, COALESCE(adjustment_amount, 0)
    INTO v_total_amount, v_adjustment
    FROM invoices
    WHERE id = p_invoice_id;

    v_effective_payable := GREATEST(0, COALESCE(v_total_amount, 0) - COALESCE(v_adjustment, 0));

    UPDATE invoices
    SET amount_paid = v_total_paid,
        pending_verification_amount = v_pending,
        paid_at = CASE
            WHEN (v_effective_payable - v_total_paid) <= 0 AND v_pending = 0 THEN COALESCE(paid_at, NOW())
            ELSE NULL
        END,
        status = CASE
            WHEN status = 'Void' THEN 'Void'
            WHEN status = 'Cancelled' THEN 'Cancelled'
            WHEN status = 'Draft' THEN 'Draft'
            WHEN (v_effective_payable - v_total_paid) <= 0 AND v_pending = 0 THEN 'Paid'
            WHEN v_total_paid > 0 THEN 'PartiallyPaid'
            WHEN COALESCE(v_adjustment, 0) > 0 AND status = 'Adjusted' THEN 'Adjusted'
            WHEN status = 'Issued' THEN 'Issued'
            ELSE 'Unpaid'
        END,
        updated_at = NOW()
    WHERE id = p_invoice_id;
END;
$$;


