--
-- Name: sp_record_child_attendance(uuid, uuid, uuid, uuid, uuid, timestamp with time zone, character varying, interval, interval, character varying, uuid, character varying, character varying, character varying, character varying, uuid, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_record_child_attendance(IN p_id uuid, IN p_tenant_id uuid, IN p_branch_id uuid, IN p_classroom_id uuid, IN p_child_id uuid, IN p_attendance_date timestamp with time zone, IN p_status character varying, IN p_arrival_time interval, IN p_departure_time interval, IN p_notes character varying, IN p_recorded_by_user_id uuid, IN p_pickup_person_name character varying, IN p_pickup_person_relationship character varying, IN p_pickup_verification_method character varying, IN p_pickup_notes character varying, IN p_authorized_pickup_id uuid, IN p_departure_verified_by_user_id uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_existing_id uuid;
BEGIN
    SELECT id INTO v_existing_id
    FROM child_attendance
    WHERE tenant_id = p_tenant_id AND child_id = p_child_id AND attendance_date = p_attendance_date::DATE
    ORDER BY created_at DESC LIMIT 1;

    IF v_existing_id IS NOT NULL THEN
        UPDATE child_attendance
        SET status = p_status,
            arrival_time = COALESCE(p_arrival_time::time, arrival_time),
            departure_time = CASE 
                WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL 
                ELSE COALESCE(p_departure_time::time, departure_time) 
            END,
            notes = COALESCE(p_notes, notes),
            pickup_person_name = CASE 
                WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL 
                ELSE COALESCE(p_pickup_person_name, pickup_person_name) 
            END,
            pickup_person_relationship = CASE 
                WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL 
                ELSE COALESCE(p_pickup_person_relationship, pickup_person_relationship) 
            END,
            pickup_verification_method = CASE 
                WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL 
                ELSE COALESCE(p_pickup_verification_method, pickup_verification_method) 
            END,
            pickup_notes = CASE 
                WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL 
                ELSE COALESCE(p_pickup_notes, pickup_notes) 
            END,
            authorized_pickup_id = CASE 
                WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL 
                ELSE COALESCE(p_authorized_pickup_id, authorized_pickup_id) 
            END,
            departure_verified_by_user_id = CASE 
                WHEN p_status = 'Present' AND p_departure_time IS NULL THEN NULL 
                ELSE COALESCE(p_departure_verified_by_user_id, departure_verified_by_user_id) 
            END,
            classroom_id = COALESCE(p_classroom_id, classroom_id),
            branch_id = COALESCE(p_branch_id, branch_id),
            recorded_by_user_id = COALESCE(p_recorded_by_user_id, recorded_by_user_id),
            updated_at = CURRENT_TIMESTAMP
        WHERE id = v_existing_id;
    ELSE
        INSERT INTO child_attendance (
            id, tenant_id, branch_id, classroom_id, child_id, attendance_date, status, 
            arrival_time, departure_time, notes, recorded_by_user_id,
            pickup_person_name, pickup_person_relationship, pickup_verification_method, pickup_notes, authorized_pickup_id, departure_verified_by_user_id,
            created_at, updated_at
        )
        VALUES (
            p_id, p_tenant_id, p_branch_id, p_classroom_id, p_child_id, p_attendance_date::DATE, p_status, 
            p_arrival_time::time, p_departure_time::time, p_notes, p_recorded_by_user_id,
            p_pickup_person_name, p_pickup_person_relationship, p_pickup_verification_method, p_pickup_notes, p_authorized_pickup_id, p_departure_verified_by_user_id,
            CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
        );
    END IF;
END;
$$;


--
-- Name: sp_record_gifting_cash_payment(uuid, uuid, numeric, uuid, character varying, character varying, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sp_record_gifting_cash_payment(p_payment_id uuid, p_order_id uuid, p_amount_received numeric, p_staff_user_id uuid, p_staff_email character varying, p_staff_name character varying, p_receipt_number character varying, p_notes text DEFAULT NULL::text) RETURNS TABLE(success boolean, message text, payment_id uuid, receipt_number character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_order classroom_gifting_orders%ROWTYPE;
BEGIN
    SELECT * INTO v_order
    FROM classroom_gifting_orders
    WHERE id = p_order_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Gifting order not found.'::TEXT, p_payment_id, ''::VARCHAR;
        RETURN;
    END IF;

    IF v_order.approval_status <> 'Approved' THEN
        RETURN QUERY SELECT FALSE, 'Payment cannot be received for an unapproved order.'::TEXT, p_payment_id, ''::VARCHAR;
        RETURN;
    END IF;

    -- Record in shared payments table
    INSERT INTO payments (
        id, tenant_id, organization_id, branch_id, child_id, gifting_order_id,
        amount, currency, method, is_verified, verified_by, verified_at,
        status, receipt_number, recorded_by_user_id, recorded_by_email,
        payment_reference, submission_source, notes, billing_domain,
        payment_date, created_at
    ) VALUES (
        p_payment_id, v_order.tenant_id, v_order.organization_id, v_order.branch_id, v_order.child_id, v_order.id,
        p_amount_received, v_order.currency, 'Cash', TRUE, p_staff_name, NOW(),
        'Completed', p_receipt_number, p_staff_user_id, p_staff_email,
        p_receipt_number, 'Staff', p_notes, 'ClassroomGifting',
        NOW(), NOW()
    );

    -- Update order payment status
    UPDATE classroom_gifting_orders
    SET payment_method = 'Cash',
        payment_status = CASE 
            WHEN p_amount_received >= v_order.total_amount THEN 'Paid'
            ELSE 'PartiallyPaid'
        END,
        updated_at = NOW()
    WHERE id = p_order_id;

    -- Record audit event
    INSERT INTO classroom_gifting_audit_events (
        order_id, tenant_id, organization_id, branch_id, classroom_id,
        event_type, previous_status, new_status, actor_user_id, actor_name,
        actor_role, description, notes
    ) VALUES (
        v_order.id, v_order.tenant_id, v_order.organization_id, v_order.branch_id, v_order.classroom_id,
        'CashPaymentReceived', v_order.payment_status, 
        CASE WHEN p_amount_received >= v_order.total_amount THEN 'Paid' ELSE 'PartiallyPaid' END,
        p_staff_user_id, p_staff_name, 'Staff',
        format('Physical cash of %s %s received by %s (Receipt #%s).', v_order.currency, p_amount_received, p_staff_name, p_receipt_number),
        p_notes
    );

    RETURN QUERY SELECT TRUE, 'Cash payment recorded and receipt generated.'::TEXT, p_payment_id, p_receipt_number;
END;
$$;


