--
-- Name: sp_reverse_dispatched_inventory(uuid, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_reverse_dispatched_inventory(IN p_order_id uuid, IN p_actor_email character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    r_item RECORD;
    v_central_id UUID;
BEGIN
    SELECT id INTO v_central_id FROM inventory_locations WHERE is_central_warehouse = true LIMIT 1;
    IF v_central_id IS NULL THEN
        RETURN;
    END IF;

    FOR r_item IN 
        SELECT material_product_id, quantity, fulfilment_mode 
        FROM material_order_items 
        WHERE order_id = p_order_id
    LOOP
        IF r_item.fulfilment_mode = 'Purchase' THEN
            -- Return from dispatched back to total and available
            CALL public.sp_update_inventory_balance_atomic(
                r_item.material_product_id,
                v_central_id,
                r_item.quantity, -- totalDelta: +qty
                r_item.quantity, -- availableDelta: +qty
                0,               -- reservedDelta
                -r_item.quantity,-- dispatchedDelta: -qty
                0, 0, 0, 0, 0, 0
            );
        ELSE -- Borrow / Loan
            -- Return from dispatched back to available
            CALL public.sp_update_inventory_balance_atomic(
                r_item.material_product_id,
                v_central_id,
                0,               -- totalDelta: 0
                r_item.quantity, -- availableDelta: +qty
                0,               -- reservedDelta
                -r_item.quantity,-- dispatchedDelta: -qty
                0, 0, 0, 0, 0, 0
            );
        END IF;

        -- Record ledger
        INSERT INTO inventory_ledger (
            id, material_product_id, location_id, transaction_type,
            quantity_delta, available_delta, reserved_delta, on_loan_delta,
            reference_type, reference_id, notes, performed_by_email, created_at
        ) VALUES (
            gen_random_uuid(), r_item.material_product_id, v_central_id, 'StockReversal',
            CASE WHEN r_item.fulfilment_mode = 'Purchase' THEN r_item.quantity ELSE 0 END,
            r_item.quantity, 0, 0,
            'OrderCancellation', p_order_id,
            'Stock restored upon cancellation/reversal of dispatched order',
            p_actor_email, NOW()
        );
    END LOOP;
END;
$$;


--
-- Name: sp_reverse_payment(uuid, character varying, text, character varying, timestamp with time zone); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_reverse_payment(IN p_payment_id uuid, IN p_reversed_by character varying, IN p_reason text, IN p_reversal_reference character varying, IN p_reversed_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE payments
    SET is_reversed = TRUE,
        status = 'Reversed',
        reversed_at = p_reversed_at,
        reversed_by = p_reversed_by,
        reversal_reason = p_reason,
        reversal_reference = p_reversal_reference
    WHERE id = p_payment_id;
END;
$$;


--
-- Name: sp_revoke_agent_token(uuid, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_revoke_agent_token(IN p_tenant_id uuid, IN p_token_id uuid)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE agent_personal_access_tokens
    SET is_revoked = TRUE, updated_at = NOW()
    WHERE id = p_token_id AND tenant_id = p_tenant_id;
END;
$$;


--
-- Name: sp_revoke_agent_token(uuid, uuid, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_revoke_agent_token(IN p_id uuid, IN p_tenant_id uuid, IN p_user_id uuid)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE agent_personal_access_tokens
    SET revoked_at = NOW()
    WHERE id = p_id AND tenant_id = p_tenant_id AND user_id = p_user_id;
END;
$$;


--
-- Name: sp_revoke_child_guardian(uuid, uuid, uuid, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_revoke_child_guardian(IN p_tenant_id uuid, IN p_child_id uuid, IN p_user_id uuid, IN p_revoked_by uuid DEFAULT NULL::uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_person_id UUID;
BEGIN
    SELECT id INTO v_person_id 
    FROM public.persons 
    WHERE tenant_id = p_tenant_id AND user_id = p_user_id 
    LIMIT 1;

    -- Revoke portal access in family_relationships
    UPDATE public.family_relationships
    SET status = 'Revoked',
        revoked_at = NOW(),
        revoked_by = p_revoked_by
    WHERE tenant_id = p_tenant_id 
      AND child_id = p_child_id 
      AND user_id = p_user_id;

    -- Deactivate pickup and communication permissions if person exists
    IF v_person_id IS NOT NULL THEN
        UPDATE public.child_guardians
        SET can_pickup = FALSE,
            can_receive_information = FALSE,
            can_authorize_medical_care = FALSE
        WHERE tenant_id = p_tenant_id 
          AND child_id = p_child_id 
          AND person_id = v_person_id;

        UPDATE public.authorized_pickups
        SET is_active = FALSE
        WHERE tenant_id = p_tenant_id 
          AND child_id = p_child_id 
          AND person_id = v_person_id;
    END IF;
END;
$$;


--
-- Name: sp_revoke_user_branch(uuid, uuid, uuid, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_revoke_user_branch(IN p_tenant_id uuid, IN p_organization_id uuid, IN p_branch_id uuid, IN p_user_id uuid)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE user_branch_assignments
    SET revoked_at = NOW()
    WHERE user_id = p_user_id
      AND branch_id = p_branch_id
      AND organization_id = p_organization_id
      AND tenant_id = p_tenant_id;
END;
$$;


--
-- Name: sp_save_authorized_pickup_with_person(uuid, uuid, text, text, text, text, text, text, uuid, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_save_authorized_pickup_with_person(IN p_tenant_id uuid, IN p_child_id uuid, IN p_first_name text, IN p_last_name text, IN p_relationship text, IN p_phone text, IN p_pickup_code text, IN p_notes text, INOUT p_pickup_id uuid, INOUT p_person_id uuid)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_person_id IS NULL OR p_person_id = '00000000-0000-0000-0000-000000000000'::uuid THEN
        p_person_id := gen_random_uuid();
        INSERT INTO persons (id, tenant_id, first_name, last_name, relationship, mobile_phone, created_at, updated_at)
        VALUES (p_person_id, p_tenant_id, p_first_name, p_last_name, COALESCE(p_relationship, 'Authorized Pickup'), p_phone, NOW(), NOW());
    ELSE
        UPDATE persons
        SET first_name = p_first_name, last_name = p_last_name, mobile_phone = p_phone, 
            relationship = COALESCE(p_relationship, 'Authorized Pickup'), updated_at = NOW()
        WHERE id = p_person_id AND (tenant_id = p_tenant_id OR tenant_id = '10000000-0000-0000-0000-000000000001');
    END IF;

    IF p_pickup_id IS NULL OR p_pickup_id = '00000000-0000-0000-0000-000000000000'::uuid THEN
        p_pickup_id := gen_random_uuid();
    END IF;

    INSERT INTO authorized_pickups (id, tenant_id, child_id, person_id, relationship, pickup_code, notes, is_active)
    VALUES (p_pickup_id, p_tenant_id, p_child_id, p_person_id, COALESCE(p_relationship, 'Authorized Pickup'), p_pickup_code, p_notes, true)
    ON CONFLICT (id) DO UPDATE
    SET person_id = EXCLUDED.person_id,
        relationship = EXCLUDED.relationship,
        pickup_code = EXCLUDED.pickup_code,
        notes = EXCLUDED.notes,
        is_active = true;
END;
$$;


--
-- Name: sp_save_child_care_plan(uuid, uuid, uuid, uuid, uuid, integer, text, text, text, text, text, text, text, text, date, date, character varying, uuid, uuid, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: PROCEDURE; Schema: public; Owner: -
