--
-- Name: sp_submit_classroom_gifting_order(uuid, character varying, uuid, uuid, uuid, uuid, uuid, character varying, character varying, uuid, character varying, uuid, character varying, text, character varying, text, character varying, character varying, numeric, character varying, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sp_submit_classroom_gifting_order(p_order_id uuid, p_order_number character varying, p_tenant_id uuid, p_organization_id uuid, p_branch_id uuid, p_classroom_id uuid, p_parent_user_id uuid, p_parent_email character varying, p_parent_name character varying, p_child_id uuid, p_recipient_type character varying, p_recipient_child_id uuid, p_recipient_child_name character varying, p_greeting_message text, p_delivery_destination_type character varying, p_confirmed_delivery_address text, p_confirmed_contact_name character varying, p_confirmed_contact_phone character varying, p_total_amount numeric, p_currency character varying, p_items_json jsonb) RETURNS TABLE(success boolean, message text, order_id uuid, order_number character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_item JSONB;
    v_product_id UUID;
    v_qty INT;
    v_avail INT;
    v_prod_name TEXT;
BEGIN
    -- 1. Validate live stock for all items with row-level locks
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items_json)
    LOOP
        v_product_id := (v_item->>'material_product_id')::UUID;
        v_qty := (v_item->>'quantity')::INT;
        v_prod_name := COALESCE(v_item->>'product_name', 'Item');

        -- Lock inventory balance row to serialize concurrent checks
        SELECT available_stock INTO v_avail
        FROM inventory_balances
        WHERE material_product_id = v_product_id
        FOR UPDATE;

        IF v_avail IS NOT NULL AND v_avail < v_qty THEN
            IF v_avail <= 0 THEN
                RETURN QUERY SELECT FALSE, 
                    format('Someone has already ordered "%s" and it is now out of stock. Please remove it from your selection.', v_prod_name), 
                    NULL::UUID, NULL::VARCHAR;
                RETURN;
            ELSE
                RETURN QUERY SELECT FALSE, 
                    format('Someone has already ordered "%s". Only %s item(s) remain in stock (you requested %s). Please adjust your quantity.', v_prod_name, v_avail, v_qty), 
                    NULL::UUID, NULL::VARCHAR;
                RETURN;
            END IF;
        END IF;
    END LOOP;

    -- 2. Deduct available stock & reserve stock atomically upon order placement
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items_json)
    LOOP
        v_product_id := (v_item->>'material_product_id')::UUID;
        v_qty := (v_item->>'quantity')::INT;

        UPDATE inventory_balances
        SET available_stock = GREATEST(0, available_stock - v_qty),
            reserved_stock = reserved_stock + v_qty,
            updated_at = NOW()
        WHERE material_product_id = v_product_id;
    END LOOP;

    -- 3. Insert order record
    INSERT INTO classroom_gifting_orders (
        id, order_number, tenant_id, organization_id, branch_id, classroom_id,
        parent_user_id, parent_email, parent_name, child_id, recipient_type,
        recipient_child_id, recipient_child_name, greeting_message,
        delivery_destination_type, confirmed_delivery_address, confirmed_contact_name,
        confirmed_contact_phone, total_amount, currency, approval_status,
        payment_status, fulfilment_status, created_at, updated_at
    ) VALUES (
        p_order_id, p_order_number, p_tenant_id, p_organization_id, p_branch_id, p_classroom_id,
        p_parent_user_id, p_parent_email, p_parent_name, p_child_id, p_recipient_type,
        p_recipient_child_id, p_recipient_child_name, p_greeting_message,
        p_delivery_destination_type, p_confirmed_delivery_address, p_confirmed_contact_name,
        p_confirmed_contact_phone, p_total_amount, COALESCE(p_currency, 'INR'), 'PendingApproval',
        'AwaitingPayment', 'NotStarted', NOW(), NOW()
    );

    -- 4. Insert items
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items_json)
    LOOP
        INSERT INTO classroom_gifting_order_items (
            order_id, material_product_id, product_name, product_sku,
            category, image_url, quantity, unit_price, line_total
        ) VALUES (
            p_order_id,
            (v_item->>'material_product_id')::UUID,
            v_item->>'product_name',
            v_item->>'product_sku',
            v_item->>'category',
            v_item->>'image_url',
            (v_item->>'quantity')::INT,
            (v_item->>'unit_price')::NUMERIC,
            (v_item->>'line_total')::NUMERIC
        );
    END LOOP;

    -- 5. Insert audit event
    INSERT INTO classroom_gifting_audit_events (
        order_id, tenant_id, organization_id, branch_id, classroom_id,
        event_type, previous_status, new_status, actor_user_id, actor_name,
        actor_role, description, notes
    ) VALUES (
        p_order_id, p_tenant_id, p_organization_id, p_branch_id, p_classroom_id,
        'OrderSubmitted', NULL, 'PendingApproval', p_parent_user_id, p_parent_name,
        'Parent', format('Order %s submitted by parent %s for amount %s %s.', p_order_number, p_parent_name, COALESCE(p_currency, 'INR'), p_total_amount),
        p_greeting_message
    );

    RETURN QUERY SELECT TRUE, 'Order submitted successfully.'::TEXT, p_order_id, p_order_number;
END;
$$;


--
-- Name: sp_submit_parent_payment(uuid, uuid, uuid, uuid, uuid, uuid, character varying, character varying, numeric, character varying, character varying, character varying, text, character varying, text, uuid, character varying, timestamp with time zone); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_submit_parent_payment(IN p_id uuid, IN p_tenant_id uuid, IN p_organization_id uuid, IN p_branch_id uuid, IN p_child_id uuid, IN p_invoice_id uuid, IN p_invoice_number character varying, IN p_payment_reference character varying, IN p_amount numeric, IN p_currency character varying, IN p_method character varying, IN p_transaction_id character varying, IN p_notes text, IN p_submission_source character varying, IN p_proof_storage_key text, IN p_recorded_by_user_id uuid, IN p_recorded_by_email character varying, IN p_payment_date timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO payments (
        id, tenant_id, organization_id, branch_id, child_id, invoice_id, invoice_number,
        payment_reference, amount, currency, method, is_verified, status, transaction_id,
        notes, submission_source, proof_storage_key, recorded_by_user_id, recorded_by_email,
        billing_domain, payment_date, created_at
    ) VALUES (
        p_id, p_tenant_id, p_organization_id, p_branch_id, p_child_id, p_invoice_id, p_invoice_number,
        p_payment_reference, p_amount, p_currency, p_method, FALSE, 'PendingVerification', p_transaction_id,
        p_notes, p_submission_source, p_proof_storage_key, p_recorded_by_user_id, p_recorded_by_email,
        'OrgToParent', p_payment_date, NOW()
    );
    CALL public.sp_recalculate_invoice_balance(p_invoice_id);
END;
$$;


--
-- Name: sp_sync_parent_external_login(character varying, character varying, character varying, character varying, character varying, character varying, uuid, uuid, uuid, uuid, boolean); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_sync_parent_external_login(IN p_provider character varying, IN p_provider_key character varying, IN p_email character varying, IN p_first_name character varying, IN p_last_name character varying, IN p_display_name character varying, IN p_default_tenant_id uuid, IN p_default_org_id uuid, INOUT io_user_id uuid DEFAULT NULL::uuid, INOUT io_tenant_id uuid DEFAULT NULL::uuid, INOUT io_is_active boolean DEFAULT NULL::boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_existing_user_id UUID;
    v_existing_tenant_id UUID;
    v_existing_is_active BOOLEAN;
    v_parent_role_id UUID;
BEGIN
    -- Check if provider key already linked
    SELECT user_id INTO v_existing_user_id
    FROM user_external_logins
    WHERE provider = p_provider AND provider_key = p_provider_key;

    IF v_existing_user_id IS NOT NULL THEN
        SELECT id, tenant_id, is_active
        INTO io_user_id, io_tenant_id, io_is_active
        FROM users
        WHERE id = v_existing_user_id;
        RETURN;
    END IF;

    -- Check if user exists by normalized email
    SELECT id, tenant_id, is_active
    INTO v_existing_user_id, v_existing_tenant_id, v_existing_is_active
    FROM users
    WHERE normalized_email = UPPER(p_email)
    LIMIT 1;

    IF v_existing_user_id IS NOT NULL THEN
        -- Reactivate if previously inactive or has active enrolled child
        UPDATE users
        SET is_active = TRUE, email_confirmed = TRUE, updated_at = NOW()
        WHERE id = v_existing_user_id;

        INSERT INTO user_external_logins (provider, provider_key, user_id, created_at)
        VALUES (p_provider, p_provider_key, v_existing_user_id, NOW())
        ON CONFLICT (provider, provider_key) DO NOTHING;

        io_user_id := v_existing_user_id;
        io_tenant_id := v_existing_tenant_id;
        io_is_active := TRUE;
    ELSE
        -- Auto-create new parent user account
        io_user_id := gen_random_uuid();
        io_tenant_id := p_default_tenant_id;
        io_is_active := TRUE;

        INSERT INTO users (
            id, tenant_id, email, normalized_email, email_confirmed,
            first_name, last_name, display_name, password_hash, security_stamp, is_active, created_at, updated_at
        ) VALUES (
            io_user_id, io_tenant_id, p_email, UPPER(p_email), TRUE,
            p_first_name, p_last_name, p_display_name, '', gen_random_uuid()::varchar, TRUE, NOW(), NOW()
        );

        INSERT INTO user_external_logins (provider, provider_key, user_id, created_at)
        VALUES (p_provider, p_provider_key, io_user_id, NOW())
        ON CONFLICT (provider, provider_key) DO NOTHING;

        -- Ensure organization membership
        INSERT INTO organization_memberships (user_id, organization_id, tenant_id, status, created_at, updated_at)
        VALUES (io_user_id, p_default_org_id, io_tenant_id, 'Active', NOW(), NOW())
        ON CONFLICT (user_id, organization_id) DO UPDATE SET status = 'Active';

        -- Assign Parent role
        SELECT id INTO v_parent_role_id
        FROM roles
        WHERE name = 'Parent' AND tenant_id = io_tenant_id
        LIMIT 1;

        IF v_parent_role_id IS NOT NULL THEN
            INSERT INTO user_organization_roles (user_id, role_id, organization_id, tenant_id)
            VALUES (io_user_id, v_parent_role_id, p_default_org_id, io_tenant_id)
            ON CONFLICT DO NOTHING;
        END IF;

        -- Ensure person record
        INSERT INTO persons (id, tenant_id, user_id, first_name, last_name, relationship, email, preferred_language, has_portal_access, receives_daily_updates, receives_photos)
        SELECT gen_random_uuid(), io_tenant_id, io_user_id, p_first_name, p_last_name, 'Parent', p_email, 'English', TRUE, TRUE, TRUE
        WHERE NOT EXISTS (SELECT 1 FROM persons WHERE user_id = io_user_id);
    END IF;
END;
$$;


--
-- Name: sp_sync_parent_guardian(uuid, uuid, character varying, character varying, character varying, character varying); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_sync_parent_guardian(IN p_tenant_id uuid, IN p_child_id uuid, IN p_parent_email character varying, IN p_parent_name character varying, IN p_relationship character varying, IN p_phone character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_norm_email VARCHAR;
    v_trimmed_email VARCHAR;
    v_user_id UUID;
    v_role_id UUID;
    v_person_id UUID;
    v_first_name VARCHAR;
    v_last_name VARCHAR;
    v_rel VARCHAR;
    v_name_parts TEXT[];
BEGIN
    IF p_parent_email IS NULL OR TRIM(p_parent_email) = '' THEN
        RETURN;
    END IF;

    v_trimmed_email := TRIM(p_parent_email);
    v_norm_email := UPPER(v_trimmed_email);
    v_rel := COALESCE(NULLIF(TRIM(p_relationship), ''), 'Parent');

    -- Split name into first and last
    v_name_parts := regexp_split_to_array(COALESCE(NULLIF(TRIM(p_parent_name), ''), 'Parent Guardian'), '\s+');
    v_first_name := v_name_parts[1];
    IF array_length(v_name_parts, 1) > 1 THEN
        v_last_name := array_to_string(v_name_parts[2:], ' ');
    ELSE
        v_last_name := 'Guardian';
    END IF;

    -- 1. Find or create User
    SELECT id INTO v_user_id FROM users WHERE normalized_email = v_norm_email LIMIT 1;
    IF v_user_id IS NULL THEN
        v_user_id := gen_random_uuid();
        INSERT INTO users (
            id, tenant_id, email, normalized_email, email_confirmed, first_name, last_name, display_name, password_hash, security_stamp, is_active, created_at, updated_at
        ) VALUES (
            v_user_id, p_tenant_id, v_trimmed_email, v_norm_email, TRUE, v_first_name, v_last_name,
            COALESCE(NULLIF(TRIM(p_parent_name), ''), v_first_name || ' ' || v_last_name),
            '', md5(random()::text), TRUE, NOW(), NOW()
        ) ON CONFLICT (normalized_email) DO NOTHING;

        SELECT id INTO v_user_id FROM users WHERE normalized_email = v_norm_email LIMIT 1;
    ELSE
        -- Ensure user is active when linked as guardian
        UPDATE users 
        SET is_active = TRUE, email_confirmed = TRUE, updated_at = NOW() 
        WHERE id = v_user_id;
    END IF;

    -- Assign role if available
    SELECT id INTO v_role_id FROM roles WHERE name = 'Parent' AND (tenant_id = p_tenant_id OR tenant_id IS NULL) LIMIT 1;
    IF v_role_id IS NOT NULL THEN
        INSERT INTO user_roles (user_id, role_id) VALUES (v_user_id, v_role_id) ON CONFLICT DO NOTHING;
    END IF;

    -- 2. Find or create Person
    SELECT id INTO v_person_id FROM persons WHERE tenant_id = p_tenant_id AND user_id = v_user_id LIMIT 1;
    IF v_person_id IS NULL THEN
        v_person_id := gen_random_uuid();
        INSERT INTO persons (
            id, tenant_id, user_id, first_name, last_name, relationship, email, mobile_phone, has_portal_access, receives_daily_updates, receives_photos, created_at, updated_at
        ) VALUES (
            v_person_id, p_tenant_id, v_user_id, v_first_name, v_last_name, v_rel, v_trimmed_email, p_phone, TRUE, TRUE, TRUE, NOW(), NOW()
        );
    ELSE
        UPDATE persons
        SET first_name = v_first_name,
            last_name = v_last_name,
            relationship = v_rel,
            mobile_phone = COALESCE(NULLIF(TRIM(p_phone), ''), mobile_phone),
            has_portal_access = TRUE,
            receives_daily_updates = TRUE,
            receives_photos = TRUE,
            updated_at = NOW()
        WHERE id = v_person_id;
    END IF;

    -- 3. Link child_guardians
    INSERT INTO child_guardians (
        id, tenant_id, child_id, person_id, relationship, is_primary, has_legal_custody, can_pickup, can_receive_information, can_authorize_medical_care
    ) VALUES (
        gen_random_uuid(), p_tenant_id, p_child_id, v_person_id, v_rel, TRUE, TRUE, TRUE, TRUE, TRUE
    ) ON CONFLICT (child_id, person_id) DO UPDATE SET
        relationship = EXCLUDED.relationship,
        can_pickup = TRUE;

    -- 4. Link family_relationships
    INSERT INTO family_relationships (
        id, tenant_id, child_id, user_id, relationship, is_primary, created_at, status, verified_at
    ) VALUES (
        gen_random_uuid(), p_tenant_id, p_child_id, v_user_id, v_rel, TRUE, NOW(), 'Verified', NOW()
    ) ON CONFLICT (child_id, user_id) DO UPDATE SET
        relationship = EXCLUDED.relationship,
        status = 'Verified',
        revoked_at = NULL,
        verified_at = NOW();

    -- 5. Link authorized_pickups
    INSERT INTO authorized_pickups (
        id, tenant_id, child_id, person_id, relationship, is_active, notes
    ) VALUES (
        gen_random_uuid(), p_tenant_id, p_child_id, v_person_id, v_rel, TRUE, 'Primary guardian on file.'
    ) ON CONFLICT DO NOTHING;
END;
$$;


--
-- Name: sp_sync_parent_relationships(uuid, character varying, character varying, character varying, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_sync_parent_relationships(IN p_user_id uuid, IN p_email character varying, IN p_first_name character varying, IN p_last_name character varying, IN p_tenant_id uuid)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- 1. Link only active, onboarded ('Enrolled') children whose enrollment draft_data matches this parent's email
    INSERT INTO family_relationships (id, tenant_id, child_id, user_id, relationship, is_primary, created_at, status, verified_at)
    SELECT gen_random_uuid(), c.tenant_id, c.id, p_user_id,
           COALESCE(NULLIF(TRIM((c.draft_data::jsonb)->>'parentRelationship'), ''), 'Parent'),
           TRUE, NOW(), 'Verified', NOW()
    FROM children c
    WHERE c.is_active = TRUE
      AND c.enrollment_status = 'Enrolled'
      AND (c.draft_data::jsonb)->>'parentEmail' ILIKE p_email
    ON CONFLICT (child_id, user_id) DO UPDATE
    SET status = 'Verified', revoked_at = NULL, verified_at = NOW();

    -- 2. Ensure person record exists for this parent only if they have an active, onboarded child
    INSERT INTO persons (id, tenant_id, user_id, first_name, last_name, relationship, email, preferred_language, has_portal_access, receives_daily_updates, receives_photos)
    SELECT gen_random_uuid(), c.tenant_id, p_user_id, p_first_name, p_last_name, 'Parent', p_email, 'English', TRUE, TRUE, TRUE
    FROM children c
    WHERE c.is_active = TRUE
      AND c.enrollment_status = 'Enrolled'
      AND (c.draft_data::jsonb)->>'parentEmail' ILIKE p_email
      AND NOT EXISTS (SELECT 1 FROM persons WHERE tenant_id = c.tenant_id AND user_id = p_user_id);
END;
$$;


--
-- Name: sp_update_admin_user(uuid, character varying, character varying, character varying, character varying, character varying, character varying, uuid); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_update_admin_user(IN p_user_id uuid, IN p_email character varying, IN p_first_name character varying, IN p_last_name character varying, IN p_password character varying, IN p_role_name character varying, IN p_account_status character varying, IN p_org_id uuid DEFAULT NULL::uuid)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_clean_email character varying;
    v_old_is_platform_admin boolean;
    v_new_is_platform_admin boolean;
    v_platform_admin_count integer;
    v_platform_role_id uuid;
    v_target_role_id uuid;
    v_tenant_id uuid;
    v_is_active boolean;
BEGIN
    v_clean_email := lower(trim(p_email));
    v_is_active := (lower(trim(p_account_status)) = 'active');
    
    SELECT id INTO v_platform_role_id FROM roles WHERE name = 'PlatformAdmin' LIMIT 1;

    -- Check if user currently has platform admin role
    SELECT EXISTS (
        SELECT 1 FROM user_roles 
        WHERE user_id = p_user_id 
          AND role_id IN (SELECT id FROM roles WHERE name IN ('PlatformAdmin', 'SuperAdmin'))
    ) INTO v_old_is_platform_admin;

    v_new_is_platform_admin := (p_role_name IN ('PlatformAdmin', 'SuperAdmin'));

    -- If promoting to platform admin from a non-platform admin role, check limit of 3
    IF v_new_is_platform_admin AND NOT v_old_is_platform_admin THEN
        SELECT COUNT(DISTINCT ur.user_id) INTO v_platform_admin_count
        FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE r.name IN ('PlatformAdmin', 'SuperAdmin');

        IF v_platform_admin_count >= 3 THEN
            RAISE EXCEPTION 'A maximum of 3 platform administrators can exist at any point in time. Please remove an existing platform administrator before promoting a new one.';
        END IF;
    END IF;

    -- If demoting from platform admin to an org role, ensure not the last one
    IF v_old_is_platform_admin AND NOT v_new_is_platform_admin THEN
        SELECT COUNT(DISTINCT ur.user_id) INTO v_platform_admin_count
        FROM user_roles ur
        JOIN roles r ON ur.role_id = r.id
        WHERE r.name IN ('PlatformAdmin', 'SuperAdmin');

        IF v_platform_admin_count <= 1 THEN
            RAISE EXCEPTION 'Cannot demote the only remaining platform administrator. At least one platform administrator must exist.';
        END IF;
    END IF;

    -- Update users table
    UPDATE users 
    SET email = v_clean_email,
        normalized_email = upper(v_clean_email),
        first_name = p_first_name,
        last_name = p_last_name,
        display_name = trim(concat(p_first_name, ' ', p_last_name)),
        is_active = v_is_active,
        password_hash = CASE WHEN p_password IS NOT NULL AND trim(p_password) != '' THEN p_password ELSE password_hash END,
        updated_at = NOW()
    WHERE id = p_user_id;

    -- Handle role transitions
    IF v_new_is_platform_admin THEN
        IF v_platform_role_id IS NOT NULL THEN
            INSERT INTO user_roles (user_id, role_id)
            VALUES (p_user_id, v_platform_role_id)
            ON CONFLICT DO NOTHING;
        END IF;
    ELSE
        -- Remove platform admin role if previously held
        IF v_platform_role_id IS NOT NULL THEN
            DELETE FROM user_roles WHERE user_id = p_user_id AND role_id = v_platform_role_id;
        END IF;

        -- Assign target organization role
        IF p_org_id IS NOT NULL THEN
            SELECT tenant_id INTO v_tenant_id FROM organizations WHERE id = p_org_id;
            IF v_tenant_id IS NULL THEN v_tenant_id := p_org_id; END IF;

            SELECT id INTO v_target_role_id 
            FROM roles 
            WHERE name = p_role_name 
              AND (tenant_id = p_org_id OR tenant_id IS NULL)
            ORDER BY tenant_id NULLS LAST 
            LIMIT 1;

            INSERT INTO organization_memberships (user_id, organization_id, tenant_id, status)
            VALUES (p_user_id, p_org_id, v_tenant_id, p_account_status)
            ON CONFLICT (user_id, organization_id) DO UPDATE SET status = p_account_status;

            IF v_target_role_id IS NOT NULL THEN
                INSERT INTO user_organization_roles (user_id, role_id, organization_id, tenant_id)
                VALUES (p_user_id, v_target_role_id, p_org_id, v_tenant_id)
                ON CONFLICT (user_id, role_id, organization_id) DO NOTHING;

                INSERT INTO user_roles (user_id, role_id)
                VALUES (p_user_id, v_target_role_id)
                ON CONFLICT DO NOTHING;
            END IF;
        END IF;
    END IF;
END;
$$;


