--
-- Name: sp_update_gifting_fulfilment_status(uuid, character varying, uuid, character varying, character varying, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sp_update_gifting_fulfilment_status(p_order_id uuid, p_target_status character varying, p_actor_user_id uuid, p_actor_name character varying, p_actor_role character varying, p_notes text DEFAULT NULL::text) RETURNS TABLE(success boolean, message text, order_id uuid, fulfilment_status character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_order classroom_gifting_orders%ROWTYPE;
    v_prev_status VARCHAR;
BEGIN
    SELECT * INTO v_order
    FROM classroom_gifting_orders
    WHERE id = p_order_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'Order not found.'::TEXT, p_order_id, ''::VARCHAR;
        RETURN;
    END IF;

    -- Enforce that unapproved or unpaid orders cannot proceed to normal fulfilment
    IF v_order.approval_status <> 'Approved' THEN
        RETURN QUERY SELECT FALSE, 'Order must be approved before updating fulfilment.'::TEXT, p_order_id, v_order.fulfilment_status;
        RETURN;
    END IF;

    v_prev_status := v_order.fulfilment_status;

    IF p_target_status = 'Preparing' THEN
        UPDATE classroom_gifting_orders
        SET fulfilment_status = 'Preparing',
            prepared_by_user_id = p_actor_user_id,
            prepared_by_name = p_actor_name,
            prepared_at = NOW(),
            updated_at = NOW()
        WHERE id = p_order_id;

    ELSIF p_target_status = 'ReadyForDelivery' THEN
        UPDATE classroom_gifting_orders
        SET fulfilment_status = 'ReadyForDelivery',
            ready_at = NOW(),
            updated_at = NOW()
        WHERE id = p_order_id;

    ELSIF p_target_status = 'DispatchedOrHandedOver' THEN
        UPDATE classroom_gifting_orders
        SET fulfilment_status = 'DispatchedOrHandedOver',
            dispatched_at = NOW(),
            updated_at = NOW()
        WHERE id = p_order_id;

    ELSIF p_target_status = 'ReceivedAtDestination' THEN
        UPDATE classroom_gifting_orders
        SET fulfilment_status = 'ReceivedAtDestination',
            received_by_user_id = p_actor_user_id,
            received_by_name = p_actor_name,
            received_at = NOW(),
            updated_at = NOW()
        WHERE id = p_order_id;

    ELSIF p_target_status = 'Distributed' THEN
        UPDATE classroom_gifting_orders
        SET fulfilment_status = 'Distributed',
            distributed_by_user_id = p_actor_user_id,
            distributed_by_name = p_actor_name,
            distributed_at = NOW(),
            distribution_notes = p_notes,
            completed_at = NOW(),
            updated_at = NOW()
        WHERE id = p_order_id;

    ELSIF p_target_status = 'Completed' THEN
        UPDATE classroom_gifting_orders
        SET fulfilment_status = 'Completed',
            completed_at = NOW(),
            updated_at = NOW()
        WHERE id = p_order_id;

    ELSE
        RETURN QUERY SELECT FALSE, 'Invalid target fulfilment status.'::TEXT, p_order_id, v_prev_status;
        RETURN;
    END IF;

    -- Audit event
    INSERT INTO classroom_gifting_audit_events (
        order_id, tenant_id, organization_id, branch_id, classroom_id,
        event_type, previous_status, new_status, actor_user_id, actor_name,
        actor_role, description, notes
    ) VALUES (
        v_order.id, v_order.tenant_id, v_order.organization_id, v_order.branch_id, v_order.classroom_id,
        'FulfilmentStatusChanged', v_prev_status, p_target_status,
        p_actor_user_id, p_actor_name, p_actor_role,
        format('Order fulfilment status updated to %s by %s (%s).', p_target_status, p_actor_name, p_actor_role),
        p_notes
    );

    RETURN QUERY SELECT TRUE, format('Fulfilment status updated to %s.', p_target_status)::TEXT, p_order_id, p_target_status;
END;
$$;


--
-- Name: sp_update_inventory_balance_atomic(uuid, uuid, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sp_update_inventory_balance_atomic(IN p_product_id uuid, IN p_location_id uuid, IN p_total_delta integer, IN p_available_delta integer, IN p_reserved_delta integer, IN p_dispatched_delta integer, IN p_on_loan_delta integer, IN p_under_inspection_delta integer, IN p_under_cleaning_delta integer, IN p_damaged_delta integer, IN p_missing_delta integer, IN p_retired_delta integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows INT;
BEGIN
    UPDATE inventory_balances SET
        total_stock = total_stock + p_total_delta,
        available_stock = GREATEST(0, available_stock + p_available_delta),
        reserved_stock = GREATEST(0, reserved_stock + p_reserved_delta),
        dispatched_stock = GREATEST(0, dispatched_stock + p_dispatched_delta),
        on_loan_stock = GREATEST(0, on_loan_stock + p_on_loan_delta),
        under_inspection_stock = GREATEST(0, under_inspection_stock + p_under_inspection_delta),
        under_cleaning_stock = GREATEST(0, under_cleaning_stock + p_under_cleaning_delta),
        damaged_stock = GREATEST(0, damaged_stock + p_damaged_delta),
        missing_stock = GREATEST(0, missing_stock + p_missing_delta),
        retired_stock = GREATEST(0, retired_stock + p_retired_delta),
        updated_at = NOW()
    WHERE material_product_id = p_product_id AND location_id = p_location_id;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        INSERT INTO inventory_balances (
            id, material_product_id, location_id, total_stock, available_stock,
            reserved_stock, dispatched_stock, on_loan_stock, under_inspection_stock,
            under_cleaning_stock, damaged_stock, missing_stock, retired_stock, updated_at
        ) VALUES (
            gen_random_uuid(), p_product_id, p_location_id,
            GREATEST(0, p_total_delta), GREATEST(0, p_available_delta),
            GREATEST(0, p_reserved_delta), GREATEST(0, p_dispatched_delta),
            GREATEST(0, p_on_loan_delta), GREATEST(0, p_under_inspection_delta),
            GREATEST(0, p_under_cleaning_delta), GREATEST(0, p_damaged_delta),
            GREATEST(0, p_missing_delta), GREATEST(0, p_retired_delta), NOW()
        )
        ON CONFLICT (material_product_id, location_id) DO UPDATE SET
            total_stock = inventory_balances.total_stock + p_total_delta,
            available_stock = GREATEST(0, inventory_balances.available_stock + p_available_delta),
            reserved_stock = GREATEST(0, inventory_balances.reserved_stock + p_reserved_delta),
            dispatched_stock = GREATEST(0, inventory_balances.dispatched_stock + p_dispatched_delta),
            on_loan_stock = GREATEST(0, inventory_balances.on_loan_stock + p_on_loan_delta),
            under_inspection_stock = GREATEST(0, inventory_balances.under_inspection_stock + p_under_inspection_delta),
            under_cleaning_stock = GREATEST(0, inventory_balances.under_cleaning_stock + p_under_cleaning_delta),
            damaged_stock = GREATEST(0, inventory_balances.damaged_stock + p_damaged_delta),
            missing_stock = GREATEST(0, inventory_balances.missing_stock + p_missing_delta),
            retired_stock = inventory_balances.retired_stock + p_retired_delta,
            updated_at = NOW();
    END IF;
END;
$$;


